const n=[{id:4001,lesson:1,level:"N5",title:"N1 は N2 です",meaning:"N1 không phải là N2",usage:["Danh từ đứng trước は là chủ đề hoặc chủ ngữ trong câu.","です được sử dụng cuối câu khẳng định, biểu lộ sự lịch sự đối với người nghe.","Đứng trước です là một danh từ hoặc tính từ.","ではありません là dạng phủ định của です.","Trong hội thoại người ta có thể dùng じゃありません thay cho ではありません"],notes:["は khi là trợ từ được đọc là wa, không phải ha","では đọc là dewa"],examples:[{ja:"N1 は",romaji:"N1 wa",vi:"N2 ではありません。"},{ja:"ラオさんは エンジニアでは（じゃ）ありません。 Anh Rao không phải là kỹ sư.",romaji:"ラオsanwa エンジニアdewa（jiゃ）arimasen。 Anh Rao không phải là kỹ sư.",vi:"Ví dụ minh họa"}]},{id:4002,lesson:1,level:"N5",title:"S+か",meaning:"S+か",usage:["1) Câu hỏi nghi vấn (câu hỏi Có Không)","Để tạo một câu hỏi chỉ cần thêm か vào cuối câu.","Câu trả lời cho loại câu hỏi này luôn phải có はい (vâng, đúng) hoặc いいえ (không,","không phải ). Nếu giản lược đi bị xem là thất lễ.","Vị trí đặt từ để hỏi chính là chỗ có từ mà bạn muốn hỏi.","Cuối câu hỏi đặt thêm trợ từ か."],notes:"Khi nói thì lên giọng ở trợ từ か",examples:[{ja:"マイさんは",romaji:"マイsanwa",vi:"ベトナム人ですか。"},{ja:"…はい、ベトナム人です。",romaji:"…wai、ベトナム人desu。",vi:"… Đúng, (bạn ấy) là người Việt Nam."},{ja:"2) ミラさんは",romaji:"2) ミラsanwa",vi:"学生ですか。"},{ja:"...いいえ、学生ではありません。",romaji:"...iie、学生dewaarimasen。",vi:"…Không, (bạn ấy) không phải là học sinh."},{ja:"…（あの人は） 山田さんです。",romaji:"…（ano人wa） 山田sandesu。",vi:"…(Người kia) Là anh Yamada."}]},{id:4003,lesson:1,level:"N5",title:"Nも",meaning:"N cũng",usage:["câu giống với những thông tin của chủ đề trước đó."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"タンさんも",romaji:"タンsanmo",vi:"ベトナム人です。"}]},{id:4004,lesson:1,level:"N5",title:"N1 の N2",meaning:"N2 của N1, N2 thuộc về N1",usage:["Trợ từ の dùng để nối 2 danh từ.","N1 làm rõ nghĩa cho N2.","Trong bài này, N1 là một tổ chức, một nhóm mà N2 thuộc vào đó."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"N1 の N2",romaji:"N1 no N2",vi:"N2 của N1, N2 thuộc về N1"}]},{id:4005,lesson:1,level:"N5",title:"～さん",meaning:"～さん",usage:["Trong tiếng Nhật sử dụng chữ さん đứng ngay sau tên của người nghe hoặc người","thứ 3 để bày tỏ sự kính trọng đối với người đó.","Chữ さん không bao giờ sử dụng sau tên của chính mình."],notes:["Khi trao đổi trực tiếp thì người Nhật ít sử dụng あなた khi đã biết tên của người","nghe, mà sẽ dùng tên để gọi. Ngoài ra, ở Nhật khi gọi một người nào đó thì gọi","nguyên cả tên và họ hoặc chỉ cần gọi họ là đủ. Chỉ gọi tên trong những trường hợp","bạn bè quen thân hay người thân trong gia đình."],examples:[{ja:"わたしは たなかです。",romaji:"watashiwa tanakadesu。",vi:"Tôi là Tanaka."},{ja:"あのかたは きむらさんです。",romaji:"anokatawa kimurasandesu。",vi:"Vị kia là Kimura."}]},{id:4006,lesson:1,level:"N5",title:"～さい",meaning:"～さい",usage:["Khi nói về tuổi thì thêm chữ さい (cách đếm tuổi) sau số thứ tự.","(Bảng đếm tuổi tham khảo trang 8)","Khi hỏi tuổi sử dụng nghi vấn từ なんさい. Trường hợp lễ phép hơn dùng từ おいく","つ."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"...（わたしは）29 さいです。",romaji:"...（watashiwa）29 saidesu。",vi:"…(Tôi ) 29 tuổi"},{ja:"... 29 です。",romaji:"... 29 desu。",vi:"…29."}]},{id:4007,lesson:2,level:"N5",title:"Các từ chỉ thị",meaning:"Cái N này/đó/kia",usage:["1） これ／それ／あれ は N です","Đây là các danh từ chỉ thị.","Được sử dụng như một danh từ.","Không có danh từ đi liền sau chúng.","これ dùng để chỉ vật ở gần người nói, xa người nghe (Trong phạm vi người nói)","それ dùng để chỉ vật ở gần người nghe, xa người nói (Trong phạm vi người nghe)","あれ dùng để chỉ vật ở xa cả hai người.","この、その、あの là các từ chỉ thị bổ nghĩa cho danh từ. Về tương quan khoảng","cách thì giống với これ、それ、あれ nhưng khác về cách sử dụng vì luôn phải có","danh từ đi liền đằng sau.","“この N” dùng để chỉ vật hoặc người ở gần người nói, xa người nghe.","“その N” dùng để chỉ vật hay người ở gần người nghe, xa người nói.","“あの N” dùng để chỉ vật hay người ở xa cả hai người.","VD: あの人は 山田さんです。 Người kia là anh Yamada."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1) これは 本ですか。",romaji:"1) korewa 本desuka。",vi:"Đây là quyển sách à?"},{ja:"…いいえ、それはノートです。",romaji:"…iie、sorewaノートdesu。",vi:"… Không, đó là quyển vở."},{ja:"2) あれは",romaji:"2) arewa",vi:"じどうしゃです。"}]},{id:4008,lesson:2,level:"N5",title:"Câu hỏi với từ để hỏi なん",meaning:"Câu hỏi với từ để hỏi なん",usage:["Nは なんですか。 N là cái gì?"],notes:["なん là từ để hỏi dùng cho vật, だれ là từ để hỏi dùng cho người.","Khi một vật ở gần cả hai người thì cả hai người đều có thể dùng これ hay この"],examples:[{ja:"…それは",romaji:"…sorewa",vi:"いすです。"},{ja:"…そのひとは",romaji:"…sonohitowa",vi:"田中さんです。"}]},{id:4009,lesson:2,level:"N5",title:"そうです／そうではありません",meaning:"そうです／そうではありません",usage:["そう được sử dụng để trả lời câu hỏi nghi vấn mà tận cùng là danh từ.","Trong câu khẳng định dùng: はい、そうです。","Trong câu phủ định dùng: いいえ、そうでは（じゃ）ありません。"],notes:["Trong trường hợp câu nghi vấn mà tận cùng là động từ hay tính từ thì không","sử dụng そうです hay そうではありません để trả lời."],examples:[{ja:"…はい、えんぴつです。",romaji:"…wai、enpitsudesu。",vi:"…Vâng, đó là cái bút chì."},{ja:"Hoặc …はい、そうです。",romaji:"Hoặc …wai、soudesu。",vi:"…Vâng, đúng vậy."},{ja:"…いいえ、テレホンカードではありません。 …Không, không phải cái thẻ điện thoại.",romaji:"…iie、テレホンカードdewaarimasen。 …Không, không phải cái thẻ điện thoại.",vi:"Ví dụ minh họa"},{ja:"Hoặc …いいえ、そうではありません。",romaji:"Hoặc …iie、soudewaarimasen。",vi:"…Không, không phải thế."}]},{id:4010,lesson:2,level:"N5",title:"N1 ですか、N2 ですか",meaning:"N1 hay là N2?",usage:["Đây là loại câu hỏi lựa chọn, được cấu tạo bởi hai câu đơn, dùng khi phân vân,","không biết rõ đối tượng là cái gì (có thể vì hình dạng khá giống nhau)","Mỗi mệnh đề trước chữ か đều là một câu hỏi về cùng 1 đối tượng"],notes:"Khi trả lời câu hỏi này không dùng はい hay いいえ",examples:[{ja:"それは ボールペンですか、シャープペンシルですか。",romaji:"sorewa ボールペンdesuka、シャープペンシルdesuka。",vi:"Đó là cái bút bi hay là bút chì kim?"},{ja:"…ボールペンです。",romaji:"…ボールペンdesu。",vi:"…Là cái bút bi."}]},{id:4011,lesson:2,level:"N5",title:"N1 の N2 (tiếp)",meaning:"N2 của N1",usage:["nghĩa chỉ sự sở hữu. N2 thuộc sở hữu của N1"],notes:["N2 đôi khi được lược bỏ khi đã được nhắc đến trước đó hay đã rõ nghĩa.","Khi N2 là một từ chỉ người thì không được bỏ."],examples:[{ja:"これは わたしの ほんです。",romaji:"korewa watashino hondesu。",vi:"Đây là quyển sách của tôi."},{ja:"あれは だれのかばんですか。",romaji:"arewa darenokabandesuka。",vi:"Kia là cái cặp của ai?"},{ja:"そのつくえは ラオさんのですか。",romaji:"sonotsukuewa ラオsannodesuka。",vi:"Cái bàn đó là của Rao phải không?"},{ja:"ミラーさんは IMC のしゃいんですか。",romaji:"ミラーsanwa IMC noshiゃindesuka。",vi:"Mira là nhân viên công ty IMC phải không?"},{ja:"… はい、IMC のしゃいんです。",romaji:"… wai、IMC noshiゃindesu。",vi:"… Vâng, (anh ấy) là nhân viên công ty IMC."},{ja:"(Không dùng : IMC のです)",romaji:"(Không dùng : IMC nodesu)",vi:"Ví dụ minh họa"}]},{id:4012,lesson:2,level:"N5",title:"そうですか",meaning:"Ra vậy",usage:["rằng đã hiểu về nó."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"A: このかさは",romaji:"A: konokasawa",vi:"あなたのですか。 Cái ô này là của bạn à?"},{ja:"B: いいえ、タンさんのです。",romaji:"B: iie、タンsannodesu。",vi:"…Không, của anh Tân."}]},{id:4013,lesson:3,level:"N5",title:"ここ・そこ・あそこ は N ( địa điểm ) です",meaning:"Chỗ này/đó/kia là N",usage:["す。","ここ、そこ、あそこ là các đại danh từ chỉ nơi chốn.","ここ chỉ chỗ của người nói. (Trong phạm vi của người nói)","そこ là chỗ của người nghe. (Trong phạm vi của người nghe)","あそこ chỉ nơi xa cả hai người."],notes:["Khi người nói và người nghe ở cùng một địa điểm thì cả hai người đều","sử dụng ここ."],examples:[{ja:"ここ・そこ・あそこ は N ( địa điểm ) です",romaji:"koko soko asoko wa N ( địa điểm ) desu",vi:"Chỗ này/đó/kia là N"}]},{id:4014,lesson:3,level:"N5",title:"N (địa điểm) はここ・そこ・あそこです。",meaning:"N ở chỗ này (chỗ đó, chỗ kia) (chỉ vị trí, tồn tại)",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"ロビーは",romaji:"ロビーwa",vi:"ここです。"},{ja:"エレベーターは",romaji:"エレベーターwa",vi:"あそこです。"}]},{id:4015,lesson:3,level:"N5",title:"Câu hỏi cho địa điểm:",meaning:"Câu hỏi cho địa điểm:",usage:["N (địa điểm) は どこ ですか。 N ở đâu?"],notes:["ó thể mở rộng trường hợp này cho địa điểm tồn tại của người và vật.","N１( người hoặc vật ) は N２ (địa điểm) です。 N1 ở N2."],examples:[{ja:"1) ラオさんは うちです。",romaji:"1) ラオsanwa uchidesu。",vi:"Anh Rao ở nhà."},{ja:"2) マイさんは あそこです。",romaji:"2) マイsanwa asokodesu。",vi:"Bạn Mai ở đằng kia."},{ja:"3) せんせいは きょうしつです。",romaji:"3) senseiwa kiょushitsudesu。",vi:"Cô giáo ở trong phòng học."},{ja:"4) マリアさんは どこですか。",romaji:"4) マリアsanwa dokodesuka。",vi:"Bạn Maria ở đâu?"},{ja:"…にわです。",romaji:"…niwadesu。",vi:"…Ngoài sân."}]},{id:4016,lesson:3,level:"N5",title:"こちら・そちら・あちら・どちら",meaning:"こちら・そちら・あちら・どちら",usage:["Nghĩa tương đương với ここ・そこ・あそこ・どこ nhưng trang trọng, lịch sự hơn.","Nghĩa gốc của chúng là các đại danh từ chỉ phương hướng."],notes:["Với câu hỏi 「あなたのかいしゃは どちらですか。」thì có thể hiểu theo 2","nghĩa: Công ty bạn ở đâu? và Công ty bạn là công ty nào? (tên công ty).","Nhưng phần lớn được hiểu theo nghĩa thứ 2. Và ở đây, quy định là hiểu theo","nghĩa thứ 2."],examples:[{ja:"（お）くには どちらですか。",romaji:"（o）kuniwa dochiradesuka。",vi:"Đất nước của bạn là ở đâu?"}]},{id:4017,lesson:3,level:"N5",title:"これ・それ・あれ は N1 の N2 です。",meaning:"Cái này/cái kia/cái đó là N2 của N1",usage:["Dùng khi muốn nói 1 đồ vật nào đó có xuất xứ từ đâu, do nước nào hoặc","công ty nào sản xuất ra"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"これ・それ・あれ は N1 の N2 です。",romaji:"kore sore are wa N1 no N2 desu。",vi:"Cái này/cái kia/cái đó là N2 của N1"}]},{id:4018,lesson:3,level:"N5",title:"Câu hỏi どこの",meaning:"Câu hỏi どこの",usage:["これ・それ・あれ は どこ の N2 ですか。","Là câu hỏi cho mẫu câu trên, dùng để hỏi xuất xứ của đồ vật, muốn biết đồ vật đó có","nguồn gốc từ đâu, do nước nào, công ty nào sản xuất.","Dùng khi muốn nói về thuộc tính của đồ vật: thuộc lĩnh vực gì, về chuyên","ngành nào, tiếng nước nào…"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"…日本 の じどうしゃです。",romaji:"…日本 no jidoushiゃdesu。",vi:"Ví dụ minh họa"},{ja:"これは じどうしゃ の ほんです。",romaji:"korewa jidoushiゃ no hondesu。",vi:"Đây là quyển sách về xe ôtô."},{ja:"それは にほんご の しんぶんです。",romaji:"sorewa nihongo no shinbundesu。",vi:"Đó là tờ báo tiếng Nhật."}]},{id:4019,lesson:3,level:"N5",title:"Câu hỏi なんの",meaning:"Câu hỏi なんの",usage:["これ・それ・あれ は なん の N ですか","Là câu hỏi cho mẫu câu trên, dùng để khi muốn hỏi 1 vật nào đó thuộc lĩnh vực gì, về","chuyên ngành nào, viết bằng tiếng nước nào…"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"… それは",romaji:"… sorewa",vi:"コンピューターのです。"},{ja:"1) FPT は コンピューターの かいしゃです。",romaji:"1) FPT wa コンピューターno kaishiゃdesu。",vi:"FPT là công ty máy tính."}]},{id:4020,lesson:3,level:"N5",title:"Nは いくらですか。",meaning:"N bao nhiêu tiền",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"このざっし は いくらですか。",romaji:"konozaっshi wa ikuradesuka。",vi:"Cái áo này bao nhiêu tiền?"},{ja:"…１００円です。",romaji:"…１００円desu。",vi:"…100 Yên"},{ja:"あの kia",romaji:"ano kia",vi:"あそこ Chỗ kia"},{ja:"100",romaji:"100",vi:"ひゃくさい"},{ja:"1000",romaji:"1000",vi:"せんさい"},{ja:"10000",romaji:"10000",vi:"いちまんさい"}]},{id:4021,lesson:4,level:"N5",title:"Bài 4 - Điểm ngữ pháp chính",meaning:"Bài 4 - Điểm ngữ pháp chính",usage:["いま じ ふん／ぷん"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 4 - Điểm ngữ pháp chính",romaji:"Bài 4 - Điểm ngữ pháp chính",vi:"Bài 4 - Điểm ngữ pháp chính"}]},{id:4022,lesson:4,level:"N5",title:"今 ～時 ～ 分 です",meaning:"Bây giờ là ~ giờ ~ phút.",usage:["ふん（ぷん）đặt sau số đếm, dùng chỉ phút.","Bảng đếm giờ","0h 1h 2h 3h 4h 5h","れいじ いちじ にじ さんじ よじ ごじ","6h 7h 8h 9h 10h 11h","ろくじ しちじ はちじ くじ じゅうじ じゅういちじ","12h ? 3:30 6 a.m 7 p.m","じゅうにじ なんじ さんじはん ごぜんろくじ ごごしちじ","Bảng đếm phút","1 2 3 4 5","いっぷん にふん さんぷん よんぷん ごふん","6 7 8 9 ?","ろっぷん ななふん はっぷん きゅうふん なんぷん","10 20 30 40 50","じゅっぷん にじゅっぷん さんじゅっぷん よんじゅっぷん ごじゅっぷん","じっぷん にじっぷん さんじっぷん よんじっぷん ごじっぷん"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"今 ～時 ～ 分 です",romaji:"今 ～時 ～ 分 desu",vi:"Bây giờ là ~ giờ ~ phút."}]},{id:4023,lesson:4,level:"N5",title:"Câu hỏi: なんじ（なんぷん）ですか。  Dùng để hỏi giờ giấc",meaning:"Câu hỏi: なんじ（なんぷん）ですか。  Dùng để hỏi giờ giấc",usage:["今 なんじ（なんぷん）ですか"],notes:["～じはん ：Sử dụng khi nói giờ rưỡi.","いま ９時 半 です。 Bây giờ là 9 rưỡi."],examples:[{ja:"Câu hỏi: なんじ（なんぷん）ですか。  Dùng để hỏi giờ giấc",romaji:"Câu hỏi: nanji（nanpun）desuka。  Dùng để hỏi giờ giấc",vi:"Câu hỏi: なんじ（なんぷん）ですか。  Dùng để hỏi giờ giấc"}]},{id:4024,lesson:4,level:"N5",title:"N (danh từ chỉ ngày) は ～曜日 です。 (Cách nói thứ ngày tháng)",meaning:"N là thứ ~.",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"N (danh từ chỉ ngày) は ～曜日 です。 (Cách nói thứ ngày tháng)",romaji:"N (danh từ chỉ ngày) wa ～曜日 desu。 (Cách nói thứ ngày tháng)",vi:"N là thứ ~."}]},{id:4025,lesson:4,level:"N5",title:"N (danh từ chỉ ngày) は 何曜日ですか。 N là thứ mấy?",meaning:"N (danh từ chỉ ngày) は 何曜日ですか。 N là thứ mấy?",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"あさっては何曜日ですか。",romaji:"asaっtewa何曜日desuka。",vi:"Ngày kia là thứ mấy?"},{ja:"… 土曜日です。",romaji:"… 土曜日desu。",vi:"Thứ bẩy."}]},{id:4026,lesson:4,level:"N5",title:"V ます (Động từ dạng ます)",meaning:"V ます (Động từ dạng ます)",usage:["một hành động ở thì hiện tại hoặc tương lai."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"V ます (Động từ dạng ます)",romaji:"V masu (Động từ dạng masu)",vi:"V ます (Động từ dạng ます)"}]},{id:4027,lesson:4,level:"N5",title:"V ます／V ません／V ました／V ませんでした (Cách chia thời của động từ)",meaning:"V ます／V ません／V ました／V ませんでした (Cách chia thời của động từ)",usage:["Cách chia thể (khẳng định, phủ định) và thời (hiện tại, quá khứ, tương lai) của động từ","dạng ～ます được thể hiện ở bảng sau:","Quá khứ Hiện tại/ Tương lai","Khẳng định ました ます","Phủ định ませんでした ません","1) まいあさ べんきょうします。 Hàng ngày tôi đều học bài.","2) あした べんきょうしません。 Ngày mai tôi sẽ không học bài.","3) きのう べんきょうしました。 Hôm qua tôi đã học bài.","4) おととい べんきょうしませんでした。 Hôm kia tôi đã không học bài."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"V ます／V ません／V ました／V ませんでした (Cách chia thời của động từ)",romaji:"V masu／V masen／V mashita／V masendeshita (Cách chia thời của động từ)",vi:"V ます／V ません／V ました／V ませんでした (Cách chia thời của động từ)"}]},{id:4028,lesson:4,level:"N5",title:"N (chỉ thời gian) に＋V ます (Cách nói 1 hành động xảy ra vào 1 thời điểm)",meaning:"làm gì vào lúc nào",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:["thời gian. Chú ý: nếu thời gian không biểu hiện bằng những con số thì không","thêm に.","Tuy nhiên, sau danh từ là các thứ trong tuần ta có thể có に hay không đều được."],examples:[{ja:"日曜日（に）べんきょうしません。",romaji:"日曜日（ni）benkiょushimasen。",vi:"Chủ nhật tôi thường không học bài."}]},{id:4029,lesson:4,level:"N5",title:"～から～まで (Cách nói khoảng thời gian, khoảng cách, từ lúc nào đến lúc",meaning:"N1 và, với, cùng với N2",usage:["nào, từ đâu đến đâu)","từ まで biểu thị điểm kết thúc của thời gian hay nơi chốn"],notes:"から và まで không nhất thiết phải sử dụng cùng nhau.",examples:[{ja:"８時半から 5時半まではたらきます。",romaji:"８時半kara 5時半madewatarakimasu。",vi:"Tôi làm việc từ 8 rưỡi đến 5 rưỡi."},{ja:"Không giống như に phải có động từ đi sau, ta có thể sử dụng です ngay sau～から、～",romaji:"Không giống như ni phải có động từ đi sau, ta có thể sử dụng desu ngay sau～kara、～",vi:"Ví dụ minh họa"},{ja:"まで hay ～から～まで.",romaji:"made hay ～kara～made.",vi:"Ví dụ minh họa"},{ja:"に ほん ご",romaji:"ni hon go",vi:"じ"},{ja:"日本語のべんきょうは",romaji:"日本語nobenkiょuwa",vi:"８時から４時までです。"},{ja:"ぎんこうの休みは",romaji:"ginkouno休miwa",vi:"土曜日と日曜日です。"}]},{id:4030,lesson:4,level:"N5",title:"(câu văn) ～ね",meaning:"(câu văn) ～ね",usage:["ね Được đặt ở cuối câu để truyền đạt cho người nghe tình cảm của mình hoặc kỳ","vọng người nghe đồng ý với những gì mình nói.","ね sẽ được phát âm dài và giọng xuống thấp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"A: 何時から何時まで",romaji:"A: 何時kara何時made",vi:"はたらきますか。"},{ja:"B: ７じはんから５じはんまでです。",romaji:"B: ７jiwankara５jiwanmadedesu。",vi:"Từ 7 rưỡi đến 5 rưỡi."},{ja:"A: たいへんですね。",romaji:"A: taiendesune。",vi:"Bạn vất vả nhỉ!"}]},{id:4031,lesson:5,level:"N5",title:"Nは ～月(がつ) ～日(にち)です。 (Cách nói ngày tháng)",meaning:"N là ngày ~ tháng ~.",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"きょうは 七月八日です。",romaji:"kiょuwa 七月八日desu。",vi:"Hôm nay là ngày mùng 8 tháng 7."},{ja:"あしたは 12日です。",romaji:"ashitawa 12日desu。",vi:"Mai là ngày 12."}]},{id:4032,lesson:5,level:"N5",title:"Câu hỏi??? (Cách hỏi ngày, tháng, thời điểm)",meaning:"Đi/Đến/Về đâu đó (địa điểm N)",usage:["N は いつですか。 N là bao giờ?","N は 何月ですか。 N là tháng mấy?","N は 何日ですか。 N là mùng mấy?","hướng di chuyển. Đi sau cùng là động từ mang nghĩa di chuyển từ nơi này sang nơi","khác."],notes:["Cách nói ngày tháng năm của Nhật ngược so với tiếng Việt. Phải nói NĂM, sau","đó đến THÁNG và cuối cùng là NGÀY","いつ có thể dùng thay thế cho các từ để hỏi có nghĩa tương tự như","なんじ、なんがつ、なんにち","2.","N (Danh từ chỉ địa điểm) へ きます (Cách nói hành động di","chuyển, đi đâu, về đâu)"],examples:[{ja:"… １４日です。",romaji:"… １４日desu。",vi:"… Ngày 14."}]},{id:4033,lesson:5,level:"N5",title:"Câu hỏi??? (Cách hỏi đi đâu, đến đâu, về đâu)",meaning:"Câu hỏi??? (Cách hỏi đi đâu, đến đâu, về đâu)",usage:["～は どこへ ～(Động từ) か。"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"どこ（へ）も",romaji:"doko（e）mo",vi:"いきません。"},{ja:"- Trợ từ も + thể phủ định của động từ: dùng để phủ định tất cả những gì trong",romaji:"- Trợ từ mo + thể phủ định của động từ: dùng để phủ định tất cả những gì trong",vi:"Ví dụ minh họa"},{ja:"phạm vi mà từ để hỏi どこ đưa ra. Có thể dùng も hoặc để cả へも đều được, nhưng",romaji:"phạm vi mà từ để hỏi doko đưa ra. Có thể dùng mo hoặc để cả emo đều được, nhưng",vi:"Ví dụ minh họa"},{ja:"dùng へも thì ý nghĩa phủ định sẽ mạnh hơn.",romaji:"dùng emo thì ý nghĩa phủ định sẽ mạnh hơn.",vi:"Ví dụ minh họa"}]},{id:4034,lesson:5,level:"N5",title:"(Cách nói cách thức di chuyển,",meaning:"(Cách nói cách thức di chuyển,",usage:["～で きます đi lại bằng phương tiện gì)","＊ Ý かえります nghĩa: Đi/đến/về bằng N (phương tiện).","Trong đó:","N là DT chỉ phương tiện giao thông, phương tiện đi lại.","で là trợ từ, mang ý nghĩa xác định cách thức, phương tiện, có thể dịch tiếng Việt","là “bằng～”, “bởi～”"],notes:["Trường hợp muốn nói là “đi bộ” thì sử dụng あるいて và không dùng で.","まいにち あるいて がっこうへ いきます。 Hàng ngày tôi đi bộ đến trường."],examples:[{ja:"わたしは じどうしゃで びょういんへ いきます。",romaji:"watashiwa jidoushiゃde biょuine ikimasu。",vi:"Tôi đi đến bệnh viện bằng ôtô."},{ja:"ラオさんは バスで わたしのうちへ きます。",romaji:"ラオsanwa バスde watashinouchie kimasu。",vi:"Bạn Rao đến nhà tôi bằng xe buýt."},{ja:"まいこさんは ひこうきで くにへ かえります。",romaji:"maikosanwa hikoukide kunie kaerimasu。",vi:"Bạn Maiko về nước bằng máy bay."}]},{id:4035,lesson:5,level:"N5",title:"Câu hỏi??? (Cách hỏi đi đâu, đến đâu, về đâu bằng cách nào, bằng",meaning:"Câu hỏi??? (Cách hỏi đi đâu, đến đâu, về đâu bằng cách nào, bằng",usage:["phương tiện gì)","〔～へ〕 なんで ～ (động từ) か。","(Đi/đến đâu bằng phương tiện gì?)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"… あるいて きました。",romaji:"… aruite kimashita。",vi:"Tôi (đã) đi bộ đến."}]},{id:4036,lesson:5,level:"N5",title:"N (Danh từ chỉ người) と V ます (Cách nói làm hành động gì cùng",meaning:"Làm gì cùng với N.",usage:["với ai)"],notes:["Trường hợp muốn nói làm gì đó “một mình” thì dùng từ ひとりで và không có と","ひとりで くにへ かえりました。 Tôi đã về nước một mình"],examples:[{ja:"ともだちと 大学へ",romaji:"tomodachito 大学e",vi:"きます。"}]},{id:4037,lesson:5,level:"N5",title:"Câu hỏi??? (Cách hỏi làm gì với ai)",meaning:"Câu hỏi??? (Cách hỏi làm gì với ai)",usage:["だれと ～ (động từ) か。","(Làm gì với ai?)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"だれと ぎんこうへ いきましたか。",romaji:"dareto ginkoue ikimashitaka。",vi:"Bạn đã đi đến ngân hàng cùng ai?"},{ja:"… ジョンさんと いきました。",romaji:"… ジョンsanto ikimashita。",vi:"Tôi đã đi với John."}]},{id:4038,lesson:5,level:"N5",title:"Sentence + よ",meaning:"Sentence + よ",usage:["よ được đặt ở cuối câu để nhấn mạnh về 1 sự việc mà người nghe chưa biết hoặc để","bộc lộ sự phán xét hay ý kiến bản thân một cách chắc chắn.","Không nên nói quá mạnh sẽ khiến người nghe có cảm giác bị ép buộc."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"このバスは",romaji:"konoバスwa",vi:"Giap Bat へ"},{ja:"...いいえ、いきません。21 ばんせんですよ。",romaji:"...iie、ikimasen。21 bansendesuyo。",vi:"Không. Đường số 21 cơ."}]},{id:4039,lesson:6,level:"N5",title:"Bài 6 - Điểm ngữ pháp chính",meaning:"Bài 6 - Điểm ngữ pháp chính",usage:["＊ Trong đó:","N: Danh từ (đối tượng của hành động)","V: Tha động từ (ngoại động từ)","を : Trợ từ (chỉ đối tượng tác động của hành động)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 6 - Điểm ngữ pháp chính",romaji:"Bài 6 - Điểm ngữ pháp chính",vi:"Bài 6 - Điểm ngữ pháp chính"}]},{id:4040,lesson:6,level:"N5",title:"(Cách đặt câu hỏi: ai đó đã/sẽ làm cái gì? )",meaning:"(Cách đặt câu hỏi: ai đó đã/sẽ làm cái gì? )",usage:["なにを V ますか。 Làm cái gì (ăn gì, uống gì, đọc gì…)?"," Câu hỏi chung cho tất cả các động từ là:","なにを しますか。 Bạn làm cái gì?"],notes:["+ も được thay cho を khi cùng chung một hành động với 2 đối tượng khác","nhau (cùng V nhưng khác N)","私は ビールを のみます。おさけも のみます。","Tôi uống bia. Uống cả rượu nữa.","+ と đươc dùng để nối 2 danh từ cùng làm đối tượng của hành động trong câu.","私は さかなと たまごを たべます。 Tôi ăn cá và trứng.","(Cách nói phủ định hoàn toàn )"],examples:[{ja:"… やさいを買いました。",romaji:"… yasaio買imashita。",vi:"Tôi đã mua rau."},{ja:"… ほんを よみます。",romaji:"… hono yomimasu。",vi:"Tôi đọc sách.."}]},{id:4041,lesson:6,level:"N5",title:"なにも V ません",meaning:"Không làm gì cả",usage:["định hoàn toàn mọi đối tượng trong phạm vi từ để hỏi."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"なにも V ません",romaji:"nanimo V masen",vi:"Không làm gì cả"}]},{id:4042,lesson:6,level:"N5",title:"N1 で N2 を V ます",meaning:"Làm ~ ở/tại N1.",usage:["địa điểm nào )"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"N1 で N2 を V ます",romaji:"N1 de N2 o V masu",vi:"Làm ~ ở/tại N1."}]},{id:4043,lesson:6,level:"N5",title:"(Cách đặt câu hỏi: ai đó đã/sẽ làm gì ở đâu? )",meaning:"(Cách đặt câu hỏi: ai đó đã/sẽ làm gì ở đâu? )",usage:["どこで V ますか。"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"(Cách đặt câu hỏi: ai đó đã/sẽ làm gì ở đâu? )",romaji:"(Cách đặt câu hỏi: ai đó đã/sẽ làm gì ở đâu? )",vi:"(Cách đặt câu hỏi: ai đó đã/sẽ làm gì ở đâu? )"}]},{id:4044,lesson:6,level:"N5",title:"いっしょに V ませんか",meaning:"Cùng làm ~ nhé!",usage:["cùng làm gì )","khác cùng làm việc gì đó với mình."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"… ええ、いいですね。",romaji:"… ee、iidesune。",vi:"… Vâng, tốt quá!"},{ja:"… すみません。ちょっと…",romaji:"… sumimasen。chiょっto…",vi:"… Xin lỗi. Nhưng mà… (cách từ chối khéo)"},{ja:"Khi muốn từ chối lời đề nghị thì dùng … すみません。ちょっと…",romaji:"Khi muốn từ chối lời đề nghị thì dùng … sumimasen。chiょっto…",vi:"“ちょっと” đi cùng"}]},{id:4045,lesson:6,level:"N5",title:"V ましょう",meaning:"Cùng làm ~ nhé!",usage:["kia sẽ đồng ý  mang tính chất thoả thuận, hô hào mọi người cùng làm","(một điều đã giao hẹn, thoả thuận từ trước)"," khác với V ませんか: dùng khi chưa biết người kia có đồng ý hay ko."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"ロビーで",romaji:"ロビーde",vi:"休みましょう。"},{ja:"はじめましょう。",romaji:"wajimemashiょu。",vi:"Nào, chúng ta bắt đầu nào!"}]},{id:4046,lesson:6,level:"N5",title:"なん／なに",meaning:"なん／なに",usage:["Cả なん và なに đều có nghĩa là “cái gì”, đều viết chung 1 chữ Hán là 何. Nhưng","cần lưu ý các trường hợp phân biệt cách dùng, cách đọc như sau:","I. Đọc là なん","1) Khi 何 đứng trước một từ bắt đầu bằng “d, n hay t”","1) 何ですか。 Cái gì vậy?","2) 何の会社ですか。 Công ty gì vậy?","2) Khi đứng sau 何 là các từ chỉ cách đếm."," 何さい"," 何ようび"," 何にち","II. Các trường hợp khác thì 何 đọc là なに","何を たべますか。 Bạn ăn gì?","何も のみませんでした。 Tôi đã không uống gì"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"なん／なに",romaji:"nan／nani",vi:"なん／なに"}]},{id:4047,lesson:7,level:"N5",title:"N で V ます (Cách thể hiện làm gì đó bằng phương cách, công cụ gì)",meaning:"Làm ~ bằng N",usage:[" Trong đó :","N: Danh từ chỉ phương tiện, công cụ","で: trợ tự chỉ phương tiện, phương thức, phương pháp thực hiện hành động"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"N で V ます (Cách thể hiện làm gì đó bằng phương cách, công cụ gì)",romaji:"N de V masu (Cách thể hiện làm gì đó bằng phương cách, công cụ gì)",vi:"Làm ~ bằng N"}]},{id:4048,lesson:7,level:"N5",title:"Câu hỏi??? (Cách hỏi làm gì bằng phương tiện, công cụ, hình thức gì )",meaning:"Câu hỏi??? (Cách hỏi làm gì bằng phương tiện, công cụ, hình thức gì )",usage:["なんで V ますか。 Làm ~ bằng gì?"],notes:"Ngoài ra, trợ từ で cũng chỉ cả phương tiện ngôn ngữ.",examples:[{ja:"日本語で",romaji:"日本語de",vi:"でんわを"}]},{id:4049,lesson:7,level:"N5",title:"(Từ/Câu) は ～語で 何ですか nói như thế nào trong tiếng nước khác)",meaning:"“Từ/Câu” trong tiếng~ là gì?",usage:["từ/câu được hỏi thường để trong dấu 「 」(dấu ngoặc kép trong tiếng Nhật)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"(1)「ありがとう」は",romaji:"(1)arigatouwa",vi:"英語で"},{ja:"…「Thank you」です。",romaji:"…Thank youdesu。",vi:"… là “Thank you”."},{ja:"(2) 「Tết」は",romaji:"(2) Tếtwa",vi:"日本語で"},{ja:"…「お 正 月 」です。",romaji:"…o 正 月 desu。",vi:"… là 「お 正 月 」"}]},{id:4050,lesson:7,level:"N5",title:"N1(người, công ty, quốc gia) に N2 を",meaning:"Làm ~ cho N1",usage:["かきます (Viết)","おしえます… (Dậy, chỉ bảo)","(Cách nói làm gì đó cho ai, hướng tới đối tượng nào)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"N1(người, công ty, quốc gia) に N2 を",romaji:"N1(người, công ty, quốc gia) ni N2 o",vi:"Làm ~ cho N1"}]},{id:4051,lesson:7,level:"N5",title:"(Cách đặt câu hỏi làm gì cho ai, hướng tới đối tượng nào)",meaning:"(Cách đặt câu hỏi làm gì cho ai, hướng tới đối tượng nào)",usage:["だれに V ますか。 Làm ~ cho ai?"],notes:["Với động từ あげます, N1 không được dùng là わたし","もらいます (Nhận được)"],examples:[{ja:"... タンさんに",romaji:"... タンsanni",vi:"おしえます。"}]},{id:4052,lesson:7,level:"N5",title:"N1(người) に N2 を かります (Vay, mượn)",meaning:"(Nhận được) ~ từ N1",usage:["ならいます (Học)","được/học được; N2: chỉ thứ hoặc vật mà chủ hành động nhận được/vay mượn được/ học","được."],notes:["Khi N1 không phải là người mà là một cơ quan/tổ chức nào đó, sẽ dùng trợ từ","から thay cho に."],examples:[{ja:"1） 木村さんは山田さんに花をもらいました。",romaji:"1） 木村sanwa山田sanni花omoraimashita。",vi:"Chị Kimura đã nhận được hoa từ Yamada."},{ja:"鈴木先生に日本語を習いました。",romaji:"鈴木先生ni日本語o習imashita。",vi:"Tôi đã học tiếng Nhật từ cô Suzuki."},{ja:"銀行から",romaji:"銀行kara",vi:"お金を借ります。"},{ja:"大学からプレゼントをもらいました。",romaji:"大学karaプレゼントomoraimashita。",vi:"Tôi đã nhận được quà từ trường đại học"}]},{id:4053,lesson:7,level:"N5",title:"(Cách đặt câu hỏi:)",meaning:"(Cách đặt câu hỏi:)",usage:["だれ に（から）V ますか。 ～ từ ai?"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"...",romaji:"...",vi:"母に"}]},{id:4054,lesson:7,level:"N5",title:"もう ＆ まだ",meaning:"もう＋V ました：đã …rồi",usage:["Câu trả lời khẳng định : はい、もう V ました。","Câu trả lời phủ định: いいえ、まだです。","(Không trả lời いいえ、まだ V ませんでした)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"... はい、もう たべました。",romaji:"... wai、mou tabemashita。",vi:"... Vâng, tôi ăn rồi."},{ja:"... いいえ、まだです。",romaji:"... iie、madadesu。",vi:"... Không, tôi vẫn chưa ăn."}]},{id:4055,lesson:8,level:"N5",title:"Giới thiệu về tính từ trong tiếng Nhật",meaning:"Giới thiệu về tính từ trong tiếng Nhật",usage:["な- Adj & い- Adj","Tính từ trong tiếng Nhật bao gồm 2 loại:","＊ Tính từ đuôi い:  Có đuôi tận cùng là い","ちい おお あつ さむ たか"],notes:["- Không giống tính từ đuôi い, do một số chức năng về ngữ pháp mà đuôi な","có lúc xuất hiện có lúc không xuất hiện trong từ và câu. Vì thế, về mặt thể","hiện, người ta hay để đuôi な trong ngoặc đơn.","Một số từ dễ nhầm với tình từ đuôi い: きれい（な）(đẹp, sạch)、有名な","(nổi tiếng)、きらい（な）(ghét, không thích)"],examples:[{ja:"＊ Tính từ đuôi な :  Có đuôi tận cùng là な",romaji:"＊ Tính từ đuôi na :  Có đuôi tận cùng là na",vi:"Ví dụ minh họa"},{ja:"しずか（な）(yên tĩnh)、べんり（な）(thuận tiện)",romaji:"shizuka（na）(yên tĩnh)、benri（na）(thuận tiện)",vi:"Ví dụ minh họa"}]},{id:4056,lesson:8,level:"N5",title:"Các mẫu câu với tính từ",meaning:"Các mẫu câu với tính từ",usage:["2.1. Câu khẳng định","Nは な-Adj [な]です","Nは い-Adj です","trong câu khẳng định để biểu thị sự lịch sự đối với người nghe.","+ Đối với tính từ đuôi な: Biến đổi như với trường hợp danh từ. Tức là đổi です","thành ではありません hoặc じゃありません"],notes:[" Chú ý: Tính từ đứng trước です, nếu là tính từ đuôi い thì giữ nguyên い còn nếu","là tính từ đuôi な thì sẽ không có な","Trường hợp đặc biệt tính từ いい sẽ đổi いいです thành よくないです","Bảng tính từ ở thời hiện tại và tương lai","Adj い-Adj な-Adj","Khẳng định い-Adj いです な-Adj [な]です","Phủ định A くないです な-Adj [な] ではありません"],examples:[{ja:"田中先生は",romaji:"田中先生wa",vi:"しんせつです。"},{ja:"富士山は",romaji:"富士山wa",vi:"高いです。"},{ja:"ハノイは",romaji:"ハノイwa",vi:"あたたかいです。"},{ja:"あの人は",romaji:"ano人wa",vi:"ゆうめいです。"},{ja:"ハノイは",romaji:"ハノイwa",vi:"静かではありません。"},{ja:"（じゃありません）",romaji:"（jiゃarimasen）",vi:"Ví dụ minh họa"},{ja:"+ Đối với tính từ đuôi い: đổi cụm いです thành くないです",romaji:"+ Đối với tính từ đuôi i: đổi cụm idesu thành kunaidesu",vi:"Ví dụ minh họa"},{ja:"この映画は",romaji:"kono映画wa",vi:"おもしろくないです。"}]},{id:4057,lesson:8,level:"N5",title:"(Cách đặt câu hỏi với tính từ: cái gì đó thế nào?)",meaning:"(Cách đặt câu hỏi với tính từ: cái gì đó thế nào?)",usage:["N は どうですか。 N thế nào?"," どう là từ để hỏi cho tính chất, cảm tưởng về vật, sự vật, người","danh từ)","い- Adj（～い）N","Khi đứng trước danh từ:","+ Tính từ đuôi な giữ nguyên な","+ Tính từ đuôi い thì giữ nguyên い"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"日本の生活は",romaji:"日本no生活wa",vi:"どうですか。"},{ja:"...",romaji:"...",vi:"楽しいです。"},{ja:"1） ジョンさんは",romaji:"1） ジョンsanwa",vi:"ハンサムな人です。"},{ja:"2） 今日は",romaji:"2） 今日wa",vi:"暑い日です。"},{ja:"3） Ａｎさんは",romaji:"3） Ａｎsanwa",vi:"ゆうめいな ひとです。"},{ja:"4） 富士山は",romaji:"4） 富士山wa",vi:"たかい山です。"}]},{id:4058,lesson:8,level:"N5",title:"あまり＋．．．phủ định của tính từ",meaning:"Không ~ lắm / Không ~ mấy",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"この食べ物は",romaji:"kono食be物wa",vi:"あまり"},{ja:"この辞書は",romaji:"kono辞書wa",vi:"あまり 便利ではありません。"},{ja:"日本語は",romaji:"日本語wa",vi:"難 しいですか。"},{ja:"...いいえ、あまり 難 しくないです。",romaji:"...iie、amari 難 shikunaidesu。",vi:"... Không, không khó lắm."}]},{id:4059,lesson:8,level:"N5",title:"(Cách đặt câu hỏi: một cái gì đó có tính chất như thế nào?)",meaning:"(Cách đặt câu hỏi: một cái gì đó có tính chất như thế nào?)",usage:["N1 は どんな N2 ですか。 N1 là N2 như thế nào?"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Hue は",romaji:"Hue wa",vi:"どんな町ですか。"},{ja:"...",romaji:"...",vi:"静かな 町です。"}]},{id:4060,lesson:8,level:"N5",title:"どう／どんな",meaning:"どう／どんな",usage:["どう・どんな đều là nghi vấn từ để hỏi về cảm tưởng, tính chất, tình trạng của người hay","vật.","Nは どうですか。 N như thế nào?","N1 は どんな N2 ですか。 N1 là N2 như thế nào?","Tuy nhiên, cần chú ý, どう thì hỏi trực tiếp vào tính chất của danh từ (không có danh từ","đằng sau) còn どんな thì hỏi 1 danh từ nào có tính chất gì (phải có danh từ đi sau)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1）日本の料理は どうですか。",romaji:"1）日本no料理wa doudesuka。",vi:"Món ăn Nhật thế nào?"},{ja:"...おいしいですが、高いです。",romaji:"...oishiidesuga、高idesu。",vi:"...Ngon nhưng đắt."},{ja:"2）鈴木さんは",romaji:"2）鈴木sanwa",vi:"どんな 人ですか。"},{ja:"...親切な人です。",romaji:"...親切na人desu。",vi:"Ví dụ minh họa"}]},{id:4061,lesson:8,level:"N5",title:"Sentence1 が、Sentence2 (Cách nói 2 vế ngược nghĩa)",meaning:"S1 nhưng mà S2",usage:["phản nhau"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"日本の食べ物は",romaji:"日本no食be物wa",vi:"どうですか。"},{ja:"... おいしいですが、高いです。",romaji:"... oishiidesuga、高idesu。",vi:"... Ngon nhưng đắt."}]},{id:4062,lesson:8,level:"N5",title:"Sentence1。そして Sentence2 (Cách nói 2 vế có nghĩa tương đồng)",meaning:"S1. Và S2",usage:["そして là liên từ có nghĩa là “và”","そして dùng để nối 2 câu có nội dung tương đồng"],notes:"＊ Chú ý: cách dùng そして khác với と (と dùng để nối 2 danh từ)",examples:[{ja:"ベトナムの食べ物は",romaji:"ベトナムno食be物wa",vi:"おいしいです。そして、安いです。"}]},{id:4063,lesson:8,level:"N5",title:"N はどれですか",meaning:"N là cái nào?",usage:["どれ： là từ để hỏi có nghía là “cái nào”","Sử dụng để yêu cầu người nghe chọn một trong số những cái đưa ra (từ 2 thứ","trở lên)."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"山田さんのとけいは",romaji:"山田sannotokeiwa",vi:"どれですか。 Đồng hồ của Yamda là cái nào?"},{ja:"... あおい",romaji:"... aoi",vi:"とけいです。"},{ja:"... あおい",romaji:"... aoi",vi:"のです。"}]},{id:4064,lesson:9,level:"N5",title:"Bài 9 - Điểm ngữ pháp chính",meaning:"Bài 9 - Điểm ngữ pháp chính",usage:["N が あります／わかります"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 9 - Điểm ngữ pháp chính",romaji:"Bài 9 - Điểm ngữ pháp chính",vi:"Bài 9 - Điểm ngữ pháp chính"}]},{id:4065,lesson:9,level:"N5",title:"す きら じょうず へ た",meaning:"す きら じょうず へ た",usage:["N が好きです／嫌 いです／上 手 です／下手です","Trong những bài trước đã học trợ từ đi với động từ là を hoặc へ.Nhưng trong bài","này trợ từ của các động từ あります／わかります là が","Một số tính từ như すき、きらい、じょうず、へた... cũng sử dụng trợ từ が"],notes:["Động từ あります chỉ sự sở hữu chỉ dùng với đồ vật, không dùng cho","người và động vật."],examples:[{ja:"1） わたしは イタリア料理が 好きです。",romaji:"1） watashiwa イタリア料理ga 好kidesu。",vi:"Tôi thích món ăn Ý."},{ja:"2） 私 の恋人は",romaji:"2） 私 no恋人wa",vi:"英語が わかります。"},{ja:"3） 田中さんは",romaji:"3） 田中sanwa",vi:"バイクが あります。"}]},{id:4066,lesson:9,level:"N5",title:"どんな N",meaning:"どんな N",usage:["cầu người nghe lựa chọn 1 thứ trong nhóm mà danh từ sau どんな","đưa ra."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"どんな 食べ物が",romaji:"donna 食be物ga",vi:"好きですか。"},{ja:"...",romaji:"...",vi:"魚が"},{ja:"どんなスポーツが 上手ですか。",romaji:"donnaスポーツga 上手desuka。",vi:"Bạn giỏi môn thể thao nào?"},{ja:"... テニスが",romaji:"... テニスga",vi:"上手です。"}]},{id:4067,lesson:9,level:"N5",title:"よく／だいたい／たくさん／少し／あまり／全然",meaning:"よく／だいたい／たくさん／少し／あまり／全然",usage:["Các phó từ あまり、ぜんぜん thường sử dụng với thể phủ định.","1) 日本語が よくわかります。 Tôi rất giỏi tiếng Nhật.","2) 英語が だいたい わかります。 Tôi biết tiếng Anh cũng đại khái thôi.","3) フランス語が あまり わかりません。 Tôi không biết tiếng Pháp nhiều lắm.","4) お金が たくさん あります。 Tôi có nhiều tiền.","5) きょうは すこし 寒いです。 Hôm nay hơi lạnh."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"よく／だいたい／たくさん／少し／あまり／全然",romaji:"yoku／daitai／takusan／少shi／amari／全然",vi:"よく／だいたい／たくさん／少し／あまり／全然"}]},{id:4068,lesson:9,level:"N5",title:"S1 から、S2 (Cách nói lý do)",meaning:"Vì S1 nên S2",usage:["から được đặt sau câu chỉ nguyên nhân.","じかん み","1) 時間が ありませんから、テレビを 見ません。 Vì không có thời gian nên tôi","không xem ti vi.","2) スポーツが 好きですから、毎日 します。 Vì thích thể thao, nên ngày nào","tôi cũng chơi."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"S1 から、S2 (Cách nói lý do)",romaji:"S1 kara、S2 (Cách nói lý do)",vi:"Vì S1 nên S2"}]},{id:4069,lesson:9,level:"N5",title:"どうして＋Sentence か。 (Câu hỏi lý do, nguyên nhân)",meaning:"Tại sao ~",usage:["Câu trả lời sẽ thêm から vào cuối câu."],notes:"âu hỏi どうしてですか。Là câu hỏi lý do chung nghĩa là “Tại sao lại thế?”",examples:[{ja:"...時間が ありませんから。",romaji:"...時間ga arimasenkara。",vi:"Vì tôi không có thời gian."},{ja:"...どうしてですか。",romaji:"...doushitedesuka。",vi:"... Tại sao thế?"},{ja:"ようじが ありますから。",romaji:"youjiga arimasukara。",vi:"Vì tôi có việc."}]},{id:4070,lesson:10,level:"N5",title:"Nが あります／います (Cách thể hiện sự sở hữu (người và đồ vật)",meaning:"Có N",usage:["あります sử dụng khi N là đồ vật","います sử dụng khi N là người và động vật"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"コンピューターが",romaji:"コンピューターga",vi:"あります。"}]},{id:4071,lesson:10,level:"N5",title:"N1(địa điểm)に N2 が あります／いま (Cách thể hiện sự tồn tại",meaning:"Có N2 ở N1 / Ở N1 có N2",usage:["(người và đồ vật)"," nhấn mạnh vào vị trí","N1 là địa điểm tồn tại của N2 và được xác định bằng trợ từ に","Nếu N2 là đồ vật: dùng あります; nếu N2 là người, động vật: dùng います"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"私 の部屋に",romaji:"私 no部屋ni",vi:"電話があります。"},{ja:"教 室 に",romaji:"教 室 ni",vi:"田中さんがいます。"}]},{id:4072,lesson:10,level:"N5",title:"(Cách đặt câu hỏi cho sự tồn tại của người, đồ vật)",meaning:"(Cách đặt câu hỏi cho sự tồn tại của người, đồ vật)",usage:["N に なにが ありますか。 Ở N (nơi chốn) có cái gì?","N に なにが いますか。 Ở N (nơi chốn) có con gì?","N に だれが いますか。 Ở N (nơi chốn) có ai?"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"… 本や ペンが あります。",romaji:"… 本ya ペンga arimasu。",vi:"Ngoài sân có con gì thế?"},{ja:"２）にわに",romaji:"２）niwani",vi:"何が いますか。"},{ja:"… 犬が います。",romaji:"… 犬ga imasu。",vi:"... Có con chó."},{ja:"３） 教 室 に だれが いますか。",romaji:"３） 教 室 ni darega imasuka。",vi:"Trong phòng học có ai thế?"},{ja:"… 鈴木先生が います。",romaji:"… 鈴木先生ga imasu。",vi:"... Có cô Suzuki."}]},{id:4073,lesson:10,level:"N5",title:"N1 は N2 (địa điểm) に あります／います (người và đồ vật)",meaning:"N1 ở N2",usage:[" nhấn mạnh vào chủ thể","N1 được đưa lên làm chủ đề của cả câu"],notes:["です thỉnh thoảng được sử dụng thay thế cho động từ chỉ vị trí あります・","います khi những động từ đó đã được nói đến hoặc đã xác định."],examples:[{ja:"ランさんの電話は",romaji:"ランsanno電話wa",vi:"うけつけにあります。"},{ja:"パソコンは",romaji:"パソコンwa",vi:"事務所に あります。"},{ja:"鈴木さんは",romaji:"鈴木sanwa",vi:"食 堂に"},{ja:"Dam Sen は",romaji:"Dam Sen wa",vi:"どこに"},{ja:"... Sai Gon",romaji:"... Sai Gon",vi:"です。"}]},{id:4074,lesson:10,level:"N5",title:"N1 (vật, người, địa điểm) の N2 (danh từ chỉ vị trí) (Cách thể hiện",meaning:"N1 (vật, người, địa điểm) の N2 (danh từ chỉ vị trí) (Cách thể hiện",usage:["tương quan vị trí)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1） つくえの 上",romaji:"1） tsukueno 上",vi:"Ví dụ minh họa"},{ja:"2） としょかんの 前",romaji:"2） toshiょkanno 前",vi:"Trước thư viện"},{ja:"3） ビルの となり",romaji:"3） ビルno tonari",vi:"Bên cạnh tòa nhà"},{ja:"1） つくえの上に",romaji:"1） tsukueno上ni",vi:"本があります。"},{ja:"2） としょかんの前に",romaji:"2） toshiょkanno前ni",vi:"こうえんがあります。"},{ja:"3） 駅の近くで",romaji:"3） 駅no近kude",vi:"ともだちと会います。"}]},{id:4075,lesson:10,level:"N5",title:"N1 や N2",meaning:"N1 và N2",usage:["や dùng để nối các danh từ","Khác với と dùng để liệt kê toàn bộ, や chỉ liệt kê mang tính chất tượng trưng."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1）きょうしつの中に",romaji:"1）kiょushitsuno中ni",vi:"つくえや いすが あります。"},{ja:"2）かばんの中に",romaji:"2）kabanno中ni",vi:"ペンや 本が あります。"},{ja:"1）きょうしつの中に",romaji:"1）kiょushitsuno中ni",vi:"つくえや いすなどが あります。"},{ja:"2）かばんの中に",romaji:"2）kabanno中ni",vi:"ペンや 本などが あります。"}]},{id:4076,lesson:11,level:"N5",title:"Bài 11 - Điểm ngữ pháp chính",meaning:"Bài 11 - Điểm ngữ pháp chính",usage:["Số đếm","＊ ひとつ、ふたつ...とお là số đếm chung cho đồ vật đến 10. Từ 11 sử dụng như đếm số","thông thường.","＊ Các trợ từ số đếm: Là những từ được đặt sau số để đếm các đồ vật, người... ( chi tiết","xem thêm trong tài liệu đính kèm )","人 dùng đếm người (đặc biệt đếm 1, 2 người dùng ひとり, ふたり)","ひき･ぴき dùng đếm con vật kích thước nhỏ","枚 dùng đếm những vật mỏng như giấy, đĩa, áo...","回 dùng đếm số lần.","Số đếm thường đứng ngay trước động từ mà nó bổ nghĩa. (giữa số đếm và động từ không","có trợ từ đứng giữa)","Tuy nhiên, với các từ chỉ khoảng thời gian lại được đặt ở mọi vị trí trong câu (trừ cuối câu)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1） りんごを 4 つ",romaji:"1） ringoo 4 tsu",vi:"買います。"},{ja:"2） 日本人の学生が",romaji:"2） 日本人no学生ga",vi:"ふたり"},{ja:"3） 国で 2 か月",romaji:"3） 国de 2 ka月",vi:"日本語を"}]},{id:4077,lesson:11,level:"N5",title:"Các từ để hỏi cho số đếm",meaning:"Các từ để hỏi cho số đếm",usage:["＊ Từ để hỏi:","いくつ là từ dùng để hỏi cho đồ vật đếm bằng ～つ","Các cách đếm khác dùng なん＋trợ từ số đếm."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"... ７つ",romaji:"... ７tsu",vi:"食べました。"},{ja:"2）きってを",romaji:"2）kiっteo",vi:"何枚"},{ja:"... ５枚",romaji:"... ５枚",vi:"買います。"}]},{id:4078,lesson:11,level:"N5",title:"どのぐらい V ますか。",meaning:"どのぐらい V ますか。",usage:["... N（lượng thời gian ）くらい（ぐらい）V ます。","どのぐらい là từ để hỏi cho khoảng thời gian","Thường đi kèm với động từ かかります(Nghĩa là: Mất bao nhiêu lâu )","くらい・ぐらい đứng sau từ chỉ số lượng, có nghĩa là “khoảng”"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"どのぐらい日本語を 勉 強 しましたか。",romaji:"donogurai日本語o 勉 強 shimashitaka。",vi:"Bạn đã học tiếng Nhật bao nhiêu lâu?"},{ja:"... 2年ぐらい",romaji:"... 2年gurai",vi:"勉 強 しました。"},{ja:"2）ハノイから ホーチミンまで",romaji:"2）ハノイkara ホーチミンmade",vi:"ひこうきで Từ Hà Nội đến TP Hồ Chí Minh đi"},{ja:"どのぐらい かかりますか。",romaji:"donogurai kakarimasuka。",vi:"bằng máy bay mất bao nhiêu lâu?"},{ja:"...二時間くらい",romaji:"...二時間kurai",vi:"かかります。"}]},{id:4079,lesson:11,level:"N5",title:"N だけ",meaning:"N だけ",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1） うちから 大学まで",romaji:"1） uchikara 大学made",vi:"5分だけ"},{ja:"2） 休みは 日曜日だけです。",romaji:"2） 休miwa 日曜日dakedesu。",vi:"Ngày nghỉ chỉ có chủ nhật."}]},{id:4080,lesson:12,level:"N5",title:"Bài 12 - Điểm ngữ pháp chính",meaning:"Bài 12 - Điểm ngữ pháp chính",usage:["Các thì của câu kết thúc bởi danh từ và tính từ đuôi な","Hiện tại Quá khứ","Khẳng N あめ N あめ","です でした","định な-adj しずか な-adj しずか","Phủ định N あめ ではありません N あめ ではありませんでした","な-adj しずか （じゃ） な-adj しずか （じゃ）"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"きのうの試験は",romaji:"kinouno試験wa",vi:"簡単ではありませんでした。"}]},{id:4081,lesson:12,level:"N5",title:"Các thì của câu kết thúc bằng tính từ đuôi い",meaning:"Các thì của câu kết thúc bằng tính từ đuôi い",usage:["Hiện tại Quá khứ","Khẳng định い-adj いです い-adj かったです","Phủ định い-adj くないです い-adj くなかったです"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1） おとといは 寒かったです。",romaji:"1） ototoiwa 寒kaっtadesu。",vi:"Hôm kia (đã) lạnh."},{ja:"2） おとといのパーティーは",romaji:"2） ototoinoパーティーwa",vi:"Bữa tiệc hôm kia (đã) không"},{ja:"あまり楽しくなかったです。",romaji:"amari楽shikunakaっtadesu。",vi:"vui lắm."}]},{id:4082,lesson:12,level:"N5",title:"N1 は N2 より Adj です。 (Cách nói so sánh hơn, kém)",meaning:"N1 ~ hơn N2",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"ひこうきは 自動車より",romaji:"hikoukiwa 自動車yori",vi:"はやいです。"},{ja:"田中さんは",romaji:"田中sanwa",vi:"私 より 高いです。"}]},{id:4083,lesson:12,level:"N5",title:"N1 と N2 と どちらが Adj ですか。 (Cách hói và nói so sánh hơn,",meaning:"Trong phạm vi N1 thì N2 ~ nhất.",usage:["...N1(N2)のほうが Adj です。 kém giữa 2 vật)","Đây là câu so sánh cao nhất","Trong đó: N2 thuộc phạm vi của N1 và có tính chất [Adj] nhất trong phạm vi đó."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"テニスとサッカーと",romaji:"テニスtoサッカーto",vi:"どちらが おもしろいですか。"},{ja:"...サッカーのほうが おもしろいです。",romaji:"...サッカーnohouga omoshiroidesu。",vi:"...Bóng đá thú vị hơn."},{ja:"春と秋と",romaji:"春to秋to",vi:"どちらが 好きですか。"},{ja:"...秋のほうが 好きです。",romaji:"...秋nohouga 好kidesu。",vi:"... Tôi thích mùa thu hơn."},{ja:"N1[のなか]で N2 が",romaji:"N1nonakade N2 ga",vi:"いちばん Adj です。"},{ja:"くだもののなかで、りんごが いちばん すきです。",romaji:"kudamonononakade、ringoga ichiban sukidesu。",vi:"Trong các loại quả, tôi thích nhất táo."},{ja:"スポーツで",romaji:"スポーツde",vi:"サッカーが いちばん おもしろいです。"},{ja:"N [のなか] で",romaji:"N nonaka de",vi:"なに／どこ／だれ／いつが"},{ja:"1年で",romaji:"1年de",vi:"いつが いちばん 寒いですか。"},{ja:"...2月が いちばん 寒いです。",romaji:"...2月ga ichiban 寒idesu。",vi:"Ví dụ minh họa"},{ja:"クラスで",romaji:"クラスde",vi:"だれが"},{ja:"… An さん です。",romaji:"… An san desu。",vi:"Bạn A (trẻ nhất)"}]},{id:4084,lesson:13,level:"N5",title:"Bài 13 - Điểm ngữ pháp chính",meaning:"Bài 13 - Điểm ngữ pháp chính",usage:["Cách thể hiện mong muốn"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 13 - Điểm ngữ pháp chính",romaji:"Bài 13 - Điểm ngữ pháp chính",vi:"Bài 13 - Điểm ngữ pháp chính"}]},{id:4085,lesson:13,level:"N5",title:"（ 私 は）N が ほしいです。",meaning:"(Tôi) muốn/ muốn có/ mong có N",usage:["(muốn có cái gì)","ほしい là tính từ đuôi い."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"私 は カメラが ほしいです。",romaji:"私 wa カメラga hoshiidesu。",vi:"Tôi muốn có máy ảnh."},{ja:"私 は 友達が",romaji:"私 wa 友達ga",vi:"ほしいです。"},{ja:"私 は 子供が",romaji:"私 wa 子供ga",vi:"ほしくないです。"}]},{id:4086,lesson:13,level:"N5",title:"Cách đặt câu hỏi về mong muốn của ai đó",meaning:"Cách đặt câu hỏi về mong muốn của ai đó",usage:["何が ほしいですか。 Bạn mong muốn, muốn có cái gì?"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"誕生日に 何が",romaji:"誕生日ni 何ga",vi:"ほしいですか。"},{ja:"...時計が ほしいです。",romaji:"...時計ga hoshiidesu。",vi:"...Tôi muốn cái đồng hồ."},{ja:"今 何が いちばん ほしいですか。",romaji:"今 何ga ichiban hoshiidesuka。",vi:"Bây giờ bạn muốn cái gì nhất?"},{ja:"...パソコンが ほしいです。",romaji:"...パソコンga hoshiidesu。",vi:"...Tôi muốn có máy tính."}]},{id:4087,lesson:13,level:"N5",title:"（私は）N を V-ます＋たいで Cách thể hiện mong muốn làm gì đó",meaning:"(Tôi) thích, muốn làm ~",usage:["す。","＊ Thể ます của động từ : Là thể của động từ khi bỏ đuôi ます.","Có thể dùng trợ từ を hoặc が(が dùng nhiều hơn). Các trợ từ khác","（に、へ、と…）giữ nguyên, không thay đổi.","Động từ thể ます+たい được coi như một tính từ đuôi い. Vì thế, cách","biến đổi sang thể phủ định hay quá khứ đều giống với tính từ đuôi い."],notes:"của người thứ ba.",examples:[{ja:"1） 私 は 日本へ",romaji:"1） 私 wa 日本e",vi:"行きたいです。"},{ja:"2） 私 は 自動車を（が）買いたいです。",romaji:"2） 私 wa 自動車o（ga）買itaidesu。",vi:"Tôi muốn mua ô tô"},{ja:"3）今、何を 食べたいですか。",romaji:"3）今、何o 食betaidesuka。",vi:"Bây giờ, bạn muốn ăn gì?"},{ja:"...何も 食べたくないです。",romaji:"...何mo 食betakunaidesu。",vi:"…Tôi chả muốn ăn gì cả"},{ja:"V-ます",romaji:"V-masu",vi:"Ví dụ minh họa"}]},{id:4088,lesson:13,level:"N5",title:"N (Địa điểm)へ に 行きます/来ます/帰ります",meaning:"Đi/đến/về N để làm ~",usage:["N","hiện hành động nào đó.","Động từ chỉ mục đích để thể ます, danh từ chỉ mục đích là những danh","động từ."],notes:["Danh từ trước に cũng có thể là các sự kiện như lễ hội, buổi hòa nhạc... Khi","đó, ý của người nói là việc xem hay tham gia vào sự kiện đó."],examples:[{ja:"1） 私 は スーパーへ 服を買いに 行きました。",romaji:"1） 私 wa スーパーe 服o買ini 行kimashita。",vi:"(Tôi đã đi siêu thị (để) mua quần áo)"},{ja:"2） 田中さんは 日本へ 日本語を 勉 強 しに 来ました。",romaji:"2） 田中sanwa 日本e 日本語o 勉 強 shini 来mashita。",vi:"(Anh Tanaka đến Nhật (để) học tiếng Nhật)"},{ja:"3）田中さんは 日本へ 日本語の 勉 強 に 来ました。",romaji:"3）田中sanwa 日本e 日本語no 勉 強 ni 来mashita。",vi:"(Anh Tanaka đến Nhật (để) học tiếng Nhật)"},{ja:"Giang Vo へ 桜 の祭りに 行きました。",romaji:"Giang Vo e 桜 no祭rini 行kimashita。",vi:"(Tôi đi đến Giảng Võ để tham gia vào Lễ hội Hoa anh đào)"}]},{id:4089,lesson:13,level:"N5",title:"どこか／なに",meaning:"どこか nghĩa là “ chỗ nào đó, nơi nào đó ” không xác định rõ",usage:["なにか được dùng như một danh từ chỉ đồ vật, sự việc","Cả 2 từ khi đứng trước các động từ đi với các trợ từ へ、が、を thì các","trợ từ này có thể được lược bỏ. Các trợ từ khác vẫn giữ nguyên"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1）夏休みは どこか（へ）行きましたか。",romaji:"1）夏休miwa dokoka（e）行kimashitaka。",vi:"Nghỉ hè, bạn có đi đâu không?"},{ja:"...はい、行きました。",romaji:"...wai、行kimashita。",vi:"Ví dụ minh họa"},{ja:"2） 暑いですから、何か（を）飲みたいです。 Vì trời nóng nên tôi muốn uống gì đó",romaji:"2） 暑idesukara、何ka（o）飲mitaidesu。 Vì trời nóng nên tôi muốn uống gì đó",vi:"Ví dụ minh họa"}]},{id:4090,lesson:14,level:"N5",title:"Các nhóm của động từ",meaning:"Các nhóm của động từ",usage:["Động từ trong tiếng Nhật được chia làm 3 nhóm theo cách chia sang các thể của chúng.","(1) Nhóm 1","Bao gồm các động từ đứng trước đuôi ます là các chữ cái thuộc hàng “i”"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Hầu hết các động từ thuộc nhóm này có dạng đứng trước đuôi ます là các chữ cái thuộc",romaji:"Hầu hết các động từ thuộc nhóm này có dạng đứng trước đuôi masu là các chữ cái thuộc",vi:"hàng “e”."},{ja:"Tuy nhiên cũng có một số động từ đứng trước đuôi ます là các chữ cái thuộc hàng “i”",romaji:"Tuy nhiên cũng có một số động từ đứng trước đuôi masu là các chữ cái thuộc hàng “i”",vi:"(3) Nhóm 3"},{ja:"Bao gồm 2 động từ: します(làm)",romaji:"Bao gồm 2 động từ: shimasu(làm)",vi:"きます(đến)"}]},{id:4091,lesson:14,level:"N5",title:"Thể て của động từ",meaning:"Thể て của động từ",usage:["Các động từ kết thúc bằng て、で được gọi là thể て. Cách chia của thể て phụ thuộc vào","các nhóm động từ. Cách chia như dưới đây:","(1) Nhóm 1:","V (i)ます Cách chia Vて Nghĩa","かきます かいて Viết","V きます－＞ V いて","ききます きいて Nghe","いそぎます V ぎます－＞ V いで いそいで Vội","のみます のんで Uống","V みます－＞ V んで","よみます よんで Đọc","（び）","よびます よんで Gọi","(に)","しにます しんで Chết","かいます かって Mua","いいます V います－＞ V って いって Nói","とります （り） とって Lấy, cầm lấy","あります （ち） あって Có","まちます ＊いきます まって Đợi","いきます いって Đi","かします かして Cho mượn","V します－＞ V して","はなします はなして Nói chuyện","(2) Nhóm 2","V (i)ます Cách chia Vて Nghĩa","食べます 食べて Ăn","おしえます おしえて Dạy","V (e)ます－＞ V (e)て","あげます あげて Cho, tặng","ねます ねて Ngủ","みます みて Xem","います いて Có (ở)","V (i)ます－＞ V (i)て","おきます おきて Thức dậy","かります かりて Mượn","(3) Nhóm 3","V (i)ます Cách chia Vて Nghĩa","べんきょうします べんきょうして Học","じっしゅうしま します －＞ して じっしゅうして Thực tập","かいものします N します－＞N して かいものして Mua sắm","けんぶつします けんぶつして Tham quan","きます きます －＞ きて きて Đến"],notes:["Khi chia sang thể て , ý nghĩa của động từ không thay đổi. Thể て là 1 thể của","động từ, dùng để cấu thành các mẫu câu khác nhau.","CÁC MẪU CÂU VỚI ĐỘNG TỪ THỂ て"],examples:[{ja:"Thể て của động từ",romaji:"Thể te của động từ",vi:"Thể て của động từ"}]},{id:4092,lesson:14,level:"N5",title:"V てください Câu nói sai khiến, nhờ vả lịch sự",meaning:"Hãy làm ~, Vui lòng làm ~",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1）ちょっと待ってください。",romaji:"1）chiょっto待っtekudasai。",vi:"Vui lòng/Xin hãy chờ một chút."},{ja:"2） 辞書を",romaji:"2） 辞書o",vi:"Ví dụ minh họa"},{ja:"貸してください。",romaji:"貸shitekudasai。",vi:"Vui lòng/Hãy cho tôi mượn quyển từ điển"},{ja:"3）ゆっくり 言ってください。",romaji:"3）yuっkuri 言っtekudasai。",vi:"Vui lòng/Hãy nói chậm lại."}]},{id:4093,lesson:14,level:"N5",title:"V ています Cách thể hiện thời tiếp diễn",meaning:"Đang làm ~",usage:["nói."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"た な か",romaji:"ta na ka",vi:"いま"},{ja:"1）田中さんは 今 日本語を勉強 しています。",romaji:"1）田中sanwa 今 日本語o勉強 shiteimasu。",vi:"Bạn Tanaka đang học tiếng Nhật."},{ja:"2） 今 雨が 降っています。",romaji:"2） 今 雨ga 降っteimasu。",vi:"Bây giờ trời đang mưa."}]},{id:4094,lesson:14,level:"N5",title:"V（thể ます）しょうか Cách thể hiện 1 lời đề nghị được làm giúp ai",meaning:"V（thể ます）しょうか Cách thể hiện 1 lời đề nghị được làm giúp ai",usage:["đó việc gì"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1）タクシーを よびましょうか。",romaji:"1）タクシーo yobimashiょuka。",vi:"Tôi gọi taxi cho bạn nhé!"},{ja:"...すみません。おねがいします。",romaji:"...sumimasen。onegaishimasu。",vi:"...Xin lỗi. Bạn giúp tôi nhé!"},{ja:"2） 荷物を",romaji:"2） 荷物o",vi:"持ちましょうか。"},{ja:"...いいえ、けっこうです。",romaji:"...iie、keっkoudesu。",vi:"...Không, tôi làm được rồi."}]},{id:4095,lesson:15,level:"N5",title:"Bài 15 - Điểm ngữ pháp chính",meaning:"Bài 15 - Điểm ngữ pháp chính",usage:["CÁC MẪU CÂU VỚI ĐỘNG TỪ DẠNG て(tiếp)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 15 - Điểm ngữ pháp chính",romaji:"Bài 15 - Điểm ngữ pháp chính",vi:"Bài 15 - Điểm ngữ pháp chính"}]},{id:4096,lesson:15,level:"N5",title:"V てもいいです Cách nói ý cho phép làm gì, làm",meaning:"Không được làm ~",usage:["gì thì được"],notes:"Thể nghi vấn của mẫu câu này được sử dụng như một câu xin phép làm gì đó",examples:[{ja:"その部屋でタバコを吸ってもいいです。 Được phép hút thuốc ở phòng đó.",romaji:"sono部屋deタバコo吸っtemoiidesu。 Được phép hút thuốc ở phòng đó.",vi:"Ví dụ minh họa"},{ja:"1）ここで 写真を撮ってもいいですか。",romaji:"1）kokode 写真o撮っtemoiidesuka。",vi:"Tôi chụp ảnh ở đây có được không?"},{ja:"...ええ、いいです。",romaji:"...ee、iidesu。",vi:"...Vâng, được."},{ja:"2） タバコを 吸ってもいいですか。",romaji:"2） タバコo 吸っtemoiidesuka。",vi:"Tôi hút thuốc có được không?"},{ja:"...すみません。いけません。",romaji:"...sumimasen。ikemasen。",vi:"...Xin lỗi. Không được."},{ja:"V ては",romaji:"V tewa",vi:"いけません"},{ja:"1）ここでタバコを吸ってはいけません。",romaji:"1）kokodeタバコo吸っtewaikemasen。",vi:"Không được hút thuốc ở đây."},{ja:"2）ここで 写真を撮ってもいいですか。",romaji:"2）kokode 写真o撮っtemoiidesuka。",vi:"Tôi chụp ảnh ở đây được không?"},{ja:"...いいえ、いけません。",romaji:"...iie、ikemasen。",vi:"Ví dụ minh họa"}]},{id:4097,lesson:15,level:"N5",title:"V ています Cách nói và ý nghĩa khác của động",meaning:"V ています Cách nói và ý nghĩa khác của động",usage:["từ dạng tiếp diễn","thể hiện ý một hành động nào đó đã diễn ra trong quá khứ và hiện tại","vẫn còn tiếp diễn, kết quả của nó vẫn hiển hiện trong hiện tại và tương","lai.","Một số động từ luôn chia ở thể tiếp diễn mặc dù hành động đã thực","し す けっこん","hiện trong quá khứ: 知っています、住んでいます、結婚していま","す、持っています","quen, những hành động được lặp đi lặp lại trong thời gian dài."],notes:"持っています ở đây mang nghĩa sở hữu.",examples:[{ja:"1） 私 は 結婚しています。",romaji:"1） 私 wa 結婚shiteimasu。",vi:"Tôi đã kết hôn (đã, và đang có gia đình)."},{ja:"2） 私 は 鈴木さんを 知っています。",romaji:"2） 私 wa 鈴木sano 知っteimasu。",vi:"Tôi biết cô Suzuki (đã và đang biết)."},{ja:"3）私は カメラを 持っています。",romaji:"3）私wa カメラo 持っteimasu。",vi:"Tôi có máy ảnh (đã và đang có)."},{ja:"4）私は ハノイに 住んでいます。",romaji:"4）私wa ハノイni 住ndeimasu。",vi:"Tôi sống ở Hà Nội (đã, đang và sẽ)"},{ja:"1）FPT は コンピューターソフトを作っています。 FPT sản xuất phần mềm máy tính.",romaji:"1）FPT wa コンピューターソフトo作っteimasu。 FPT sản xuất phần mềm máy tính.",vi:"Ví dụ minh họa"},{ja:"2）私は",romaji:"2）私wa",vi:"CMC で"},{ja:"3）私は",romaji:"3）私wa",vi:"FPT大学で"}]},{id:4098,lesson:16,level:"N5",title:"V１て、V2 て...V ます Cách nối 2 hay nhiều động từ",meaning:"Làm V1 rồi làm V2,...",usage:["(thể hiện ý liệt kê hành động)","hành động đứng trước xẩy ra trước.","Thì của cả câu được chia ở động từ cuối cùng."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1）毎朝 ジョギングをして、シャワーを浴びて、学校へ行きます。",romaji:"1）毎朝 ジョギングoshite、シャワーo浴bite、学校e行kimasu。",vi:"(Hàng sáng tôi chạy bộ rồi tắm sau đó đến trường.)"}]},{id:4099,lesson:16,level:"N5",title:"い- adj(～い) ～くて、～ Cách nối 2 hay nhiều tính từ với",meaning:"い- adj(～い) ～くて、～ Cách nối 2 hay nhiều tính từ với",usage:["な-adj [な] で、～ nhau, 2 hay nhiều danh từ với nhau","N で、～","đuôi い thì đuôi い sẽ được bỏ đi thay thế bằng くて, các tính từ có thể","được cách nhau bởi dấu phẩy ( 、).","大きい 新しい 大きくて、新しい (to và mới)","小さい 古い 小さくて、古い (nhỏ và cũ)","いい 安い よくて、安い (tốt và rẻ)","Khi nối 2 hay nhiều tính từ của cùng 1 chủ thể, nếu đi trước là tính từ","đuôi な thì đuôi な sẽ được bỏ đi thay thế bằng で, các tính từ có thể được","cách nhau bởi dấu phẩy ( 、).","元気（な） 若い 元気で、若い (khỏe và trẻ)","有名（な） きれい（な） 有名で、きれい (nổi tiếng và đẹp)","Cách nối đó có nghĩa là “ và ” vì vậy không sử dụng để nối 2 câu có ý","nghĩa trái ngược.","Thì của cả câu được chia ở câu đứng sau."],notes:["Riêng cấu trúc với danh từ, không nhất thiết chỉ sử dụng khi có cùng chủ","ngữ, có thể là 2 câu có chủ ngữ khác nhau (trong trường hợp này, nó sẽ trở thành","cách kết hợp 2 câu với nhau)"],examples:[{ja:"す ず き",romaji:"su zu ki",vi:"わか"},{ja:"1）鈴木さんは 若くて、元気です。",romaji:"1）鈴木sanwa 若kute、元気desu。",vi:"Cô Suzuki trẻ và khỏe mạnh."},{ja:"2）ハノイは 人が多くて、にぎやかです。",romaji:"2）ハノイwa 人ga多kute、nigiyakadesu。",vi:"Hà Nội đông người và nhộn nhịp."},{ja:"ラオさんは ハンサムで、親切です。",romaji:"ラオsanwa ハンサムde、親切desu。",vi:"Anh Rao đẹp trai và tốt bụng."},{ja:"Hue は 静かで、きれいな町です。",romaji:"Hue wa 静kade、kireina町desu。",vi:"Huế là thành phố yên tĩnh và đẹp."},{ja:"田中さんは 日本人で、留学生です。",romaji:"田中sanwa 日本人de、留学生desu。",vi:"Ví dụ minh họa"},{ja:"に ほ ん じ ん",romaji:"ni ho n ji n",vi:"りゅうがくせい"},{ja:"カリナさんは 研修生で、マリアさんは 主婦です。",romaji:"カリナsanwa 研修生de、マリアsanwa 主婦desu。",vi:"(Karina là tu nghiệp sinh còn Maria là vợ.)"}]},{id:4100,lesson:16,level:"N5",title:"V１てから、V2 ます Cách nói làm gì sau khi làm gì",meaning:"Làm V1 rồi làm V2 / Sau",usage:["hành động thứ nhất kết thúc rối mới đến hành động 2.","Thì của cả câu được quyết định ở cuối câu."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1）国へ帰ってから、父の会社で 働 きます。",romaji:"1）国e帰っtekara、父no会社de 働 kimasu。",vi:"Sau khi về nước tôi sẽ làm việc ở công ty của bố."},{ja:"2）コンサートが 終わってから、レストランで 食事しました。",romaji:"2）コンサートga 終waっtekara、レストランde 食事shimashita。",vi:"Sau khi kết thúc buổi biểu diễn âm nhạc tôi đã ăn ở nhà hàng."}]},{id:4101,lesson:16,level:"N5",title:"N1 は N2 が Adj",meaning:"N1 は N2 が Adj",usage:["vật hoặc người."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Hue は",romaji:"Hue wa",vi:"食べ物が おいしいです。 Đồ ăn Huế ngon."},{ja:"マリアさんは 髪が 長いです。",romaji:"マリアsanwa 髪ga 長idesu。",vi:"Maria có mái tóc dài."},{ja:"た な か",romaji:"ta na ka",vi:"せ"},{ja:"田中さんは 背が",romaji:"田中sanwa 背ga",vi:"高いです 。"}]},{id:4102,lesson:16,level:"N5",title:"どうやって",meaning:"どうやって",usage:["Đây là từ để hỏi cho cách làm, phương thức làm một việc nào đó và có nghĩa là “ Làm","thế nào” Để trả lời cho câu hỏi này thường sử dụng mẫu câu số 1"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"大学まで どうやって",romaji:"大学made douyaっte",vi:"行きますか。"},{ja:"...バス乗り場まで 5分ぐらいあるいて、16番のバスに乗って、大学前でおります。",romaji:"...バス乗ri場made 5分guraiaruite、16番noバスni乗っte、大学前deorimasu。",vi:"...Tôi đi bộ khoảng 5 phút đến bến xe bus, lên xe số 16 và xuống ở đằng trước trường."}]},{id:4103,lesson:16,level:"N5",title:"どの N",meaning:"どの N",usage:["các từ đó và có nghĩa là “nào”.","Đằng sau どの luôn là một danh từ."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"た な か",romaji:"ta na ka",vi:"ひと"},{ja:"田中さんは どの人ですか。",romaji:"田中sanwa dono人desuka。",vi:"Tanaka là người nào?"},{ja:"...あの背が高くて、髪が 黒い人です。",romaji:"...ano背ga高kute、髪ga 黒i人desu。",vi:"...Là người cao và tóc màu đen."}]},{id:4104,lesson:17,level:"N5",title:"V ない Cách chia và các mẫu câu với động",meaning:"V ない Cách chia và các mẫu câu với động",usage:["từ phủ định dạng ngắn (thể ない)","＊ Động từ đi với ない được gọi là thể ない (còn gọi là động từ phủ định dạng ngắn)","＊ Cách chia :"," Nhóm I : là các động từ đều có vần [-i] đứng trước ます. Để chuyển sang thể ない","chỉ cần thay thế [-i] bằng vần [-a]. Trường hợp đặc biệt, những động từ có đuôi là","い thì chuyển thành わ."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"あい－ます →",romaji:"ai－masu →",vi:"あわ－ない"},{ja:"かき－ます →",romaji:"kaki－masu →",vi:"かか－ない"},{ja:"いそぎ－ます →",romaji:"isogi－masu →",vi:"いそが－ない"},{ja:"はなし－ます →",romaji:"wanashi－masu →",vi:"はなさ－ない"},{ja:"まち－ます →",romaji:"machi－masu →",vi:"また－ない"},{ja:"あそび－ます →",romaji:"asobi－masu →",vi:"あそば－ない"},{ja:"よみ－ます →",romaji:"yomi－masu →",vi:"よま－ない"},{ja:"とり－ます →",romaji:"tori－masu →",vi:"とら－ない"},{ja:" Nhóm II:bỏ [-ます] thêm ない",romaji:" Nhóm II:bỏ -masu thêm nai",vi:"Ví dụ minh họa"},{ja:"たべ－ます →",romaji:"tabe－masu →",vi:"たべ－ない"},{ja:"み－ます →",romaji:"mi－masu →",vi:"み－ない"},{ja:"し－ます →",romaji:"shi－masu →",vi:"し－ない"},{ja:"き－ます →",romaji:"ki－masu →",vi:"こ－ない"},{ja:"CÁC MẪU CÂU VỚI ĐỘNG TỪ DẠNG ない",romaji:"CÁC MẪU CÂU VỚI ĐỘNG TỪ DẠNG nai",vi:"Ví dụ minh họa"}]},{id:4105,lesson:17,level:"N5",title:"V ないで ください Câu sai khiến, nhờ vả, khuyên bảo lịch sự ở",meaning:"Xin đừng…",usage:["dạng phủ định  hãy đừng…, xin đừng…"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1） 私 は 元気ですから、心配しないで",romaji:"1） 私 wa 元気desukara、心配shinaide",vi:"ください。"},{ja:"2）ここで 写真を 撮らないで",romaji:"2）kokode 写真o 撮ranaide",vi:"ください。"}]},{id:4106,lesson:17,level:"N5",title:"V なければ なりません Cách nói bắt buộc",meaning:"phải…, bắt buộc phải…",usage:[" phải làm gì","＊ Cách chia: động từ chia sang thể ない, bỏ い + ければ なりません","hướng của người làm."],notes:["- Chú ý: Mặc dù động từ chia ở dạng phủ định nhưng cả câu không mang","nghĩa phủ định (thực chất là phủ định của phủ định  “không làm gì thì","không được”)"],examples:[{ja:"1） 薬 を 飲まなければなりません。",romaji:"1） 薬 o 飲manakerebanarimasen。",vi:"(Phải uống thuốc)"},{ja:"2）毎日 日本語を 勉 強 しなければなりません。",romaji:"2）毎日 日本語o 勉 強 shinakerebanarimasen。",vi:"(Hàng ngày (tôi) phải học tiếng Nhật.)"}]},{id:4107,lesson:17,level:"N5",title:"V なくても いいです Cách nói cho phép ở dạng phủ định",meaning:"không cần … cũng được",usage:[" không làm gì cũng được"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"1）明日 来なくても いいです。",romaji:"1）明日 来nakutemo iidesu。",vi:"(Ngài mai bạn không đến cũng được)"},{ja:"ど よ う び",romaji:"do yo u bi",vi:"ご ご"},{ja:"2） 土曜日の午後 勉 強 しなくても",romaji:"2） 土曜日no午後 勉 強 shinakutemo",vi:"いいです。"},{ja:"1）明日 来なくても いいですか。",romaji:"1）明日 来nakutemo iidesuka。",vi:"(Ngài mai không đến cũng được chứ ạ?)"},{ja:"ど よ う び",romaji:"do yo u bi",vi:"ご ご"},{ja:"2） 土曜日の午後 勉 強 しなくても いいですか。",romaji:"2） 土曜日no午後 勉 強 shinakutemo iidesuka。",vi:"(Chiều thứ 7 không học có được không ạ?)"}]},{id:4108,lesson:17,level:"N5",title:"N (tân ngữ) は Cách nói nhấn mạnh vào tân ngữ",meaning:"đưa tân ngữ lên làm chủ đề nhằm nhấn mạnh ý muốn diễn tả",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"１）ここに 荷物を",romaji:"１）kokoni 荷物o",vi:"置かないでください。(Đừng để hành lý ở đây)"},{ja:"２）会社の",romaji:"２）会社no",vi:"食 堂 で 昼ごはんを 食べます。(Tôi ăn cơm trưa tại nhà ăn công ty)"},{ja:"→ 昼ごはんは 会社の",romaji:"→ 昼gowanwa 会社no",vi:"食 堂 で 食べます。( Cơm trưa thì tôi ăn tại nhà ăn cty)"}]},{id:4109,lesson:17,level:"N5",title:"N(thời gian)までに V Trợ từ chỉ giới hạn, hạn định",meaning:"chậm nhất, trễ nhất, trước (thời điểm)",usage:["hành. Có nghĩa là, hành động hay công việc phải được tiến hành trước","thời hạn được chỉ định bởi までに"],notes:["phân biệt までに với trợ từ まで và trợ từ に","① まで：chỉ thời điểm chấm dứt một hành động","ひる じ に ほ ん ご べんきょう","昼 １２時まで 日本語を 勉 強 します。","(Buổi trưa, tôi học đến 12 giờ)","② に：chỉ thời điểm mà một hành động diễn ra.","朝 ６時に 起きます。","(Tôi thức dậy vào lúc 6 giờ)"],examples:[{ja:"１）会議は ５時までに 終わります。",romaji:"１）会議wa ５時madeni 終warimasu。",vi:"(Cuộc họp sẽ kết thúc trước 5 giờ)"},{ja:"ど よ う び",romaji:"do yo u bi",vi:"ほん"},{ja:"２）土曜日までに 本を 返さなければなりません。",romaji:"２）土曜日madeni 本o 返sanakerebanarimasen。",vi:"(Phải trả sách trước thứ 7)"}]},{id:4110,lesson:18,level:"N5",title:"Bài 18 - Điểm ngữ pháp chính",meaning:"Bài 18 - Điểm ngữ pháp chính",usage:["ĐỘNG TỪ THỂ TỪ ĐIỂN (V る) & MẪU CÂU"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 18 - Điểm ngữ pháp chính",romaji:"Bài 18 - Điểm ngữ pháp chính",vi:"Bài 18 - Điểm ngữ pháp chính"}]},{id:4111,lesson:18,level:"N5",title:"Thể nguyên mẫu (thể từ điển) của động từ",meaning:"Thể nguyên mẫu (thể từ điển) của động từ",usage:["Thể nguyên mẫu (còn gọi là thể từ điển) là thể cơ bản (động từ gốc) của động từ, trong","sách từ điển các động từ được trình bày ở thể này.","(1) Nhóm 1  Ký hiệu G1 hoặc (I)","Là các động từ có kết thúc bởi các âm sau:","[-う] ]、 [-つ] 、[-る] [-む] ]、 [-ぬ] 、[-ぶ] [-す] ]、 [-く] 、[-ぐ]"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"（かいます ←）",romaji:"（kaimasu ←）",vi:"かう"},{ja:"（まちます",romaji:"（machimasu",vi:"←）"},{ja:"（とります",romaji:"（torimasu",vi:"←）"},{ja:"（すみます",romaji:"（sumimasu",vi:"←）"},{ja:"（しにます",romaji:"（shinimasu",vi:"←）"},{ja:"（よびます",romaji:"（yobimasu",vi:"←）"},{ja:"（はなします",romaji:"（wanashimasu",vi:"←） はなす"},{ja:"（かきます ←）",romaji:"（kakimasu ←）",vi:"かく"},{ja:"（およぎます ←）",romaji:"（oyogimasu ←）",vi:"およぐ"},{ja:"Là các động từ có dạng [-e る] [-i る]",romaji:"Là các động từ có dạng -e ru -i ru",vi:"Ví dụ minh họa"},{ja:"（たべます ←） たべる (ăn)",romaji:"（tabemasu ←） taberu (ăn)",vi:"Ví dụ minh họa"},{ja:"（みます",romaji:"（mimasu",vi:"←）"},{ja:"（かえります",romaji:"（kaerimasu",vi:"←） かえる (trở về)"},{ja:"（しります",romaji:"（shirimasu",vi:"←） しる (biết)"},{ja:"（します",romaji:"（shimasu",vi:"→） する"},{ja:"（きます",romaji:"（kimasu",vi:"→） くる"}]},{id:4112,lesson:18,level:"N5",title:"N Cách thể hiện khả năng",meaning:"có thể làm…, biết làm…",usage:["V ること が できます","a) Trường hợp danh từ: danh từ được sử dụng phải có tính động tác (tức là những","danh từ có thể ghép với し ます để trở thành động từ có nghĩa tương ứng ) như:","運転、買い物、ダンス ( gọi chung là danh động từ) ... Ngoài ra, các danh từ","chỉ về những khả năng như 日本語、ピアノ、スキー cũng có thể sử dụng."],notes:["Nghĩa của động từ できます","① Năng lực","漢字を 読むことが できます。( Biết đọc chữ Hán)","② Khả năng","うけつけ た く し よ","受付で タクシーを 呼ぶことが できます。( Có thể gọi taxi tại quầy lễ tân)"],examples:[{ja:"１）運転が できます。",romaji:"１）運転ga dekimasu。",vi:"(Tôi biết/có thể lái xe)"},{ja:"２）ミラーさんは 日本語が できます。",romaji:"２）ミラーsanwa 日本語ga dekimasu。",vi:"(Anh Miler biết tiếng Nhật (có thể nói tiếng Nhật))"},{ja:"phải thêm こと sau động từ thể nguyên mẫu để biến thành một nhóm danh từ.",romaji:"phải thêm koto sau động từ thể nguyên mẫu để biến thành một nhóm danh từ.",vi:"( danh từ hóa)"},{ja:"１）ミラーさんは 漢字を 読むことが できます。",romaji:"１）ミラーsanwa 漢字o 読mukotoga dekimasu。",vi:"(Anh Miler biết/có thể đọc được chữ Hán)"},{ja:"２）カードで 払うことが できます。",romaji:"２）カードde 払ukotoga dekimasu。",vi:"(Có thể thanh toán/trả tiền bằng thẻ)"}]},{id:4113,lesson:18,level:"N5",title:"私の 趣味は N です Cách thể hiện sở thích",meaning:"sở thích (của tôi) là…",usage:["V ること","Khi một danh từ không thể biểu hiện đầy đủ ý nghĩa thì ta có thể diễn","tả dùng cách danh từ hóa để trình bày rõ, cụ thể hơn"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"１）私の趣味は 絵です。",romaji:"１）私no趣味wa 絵desu。",vi:"(Sở thích của tôi là hội họa)"},{ja:"２）私の趣味は 絵を描くことです。 (Sở thích của tôi là (việc) vẽ tranh)",romaji:"２）私no趣味wa 絵o描kukotodesu。 (Sở thích của tôi là (việc) vẽ tranh)",vi:"Ví dụ minh họa"},{ja:"３）私の趣味は 絵を見ることです。 (Sở thích của tôi là (việc) ngắm tranh)",romaji:"３）私no趣味wa 絵o見rukotodesu。 (Sở thích của tôi là (việc) ngắm tranh)",vi:"Ví dụ minh họa"}]},{id:4114,lesson:18,level:"N5",title:"Vる Cách nói câu “trước khi",meaning:"làm V2 trước..., trước khi làm V1…",usage:["Nの まえに、V2 làm gì thì làm gì”","Số tự (thời gian)","a) Động từ","Hành động thứ 2 diễn ra trước hành động thứ nhất.","Không thay đổi theo thì của động từ. Nghĩa là khi thì của động từ thứ 2 là quá","khứ hay tương lai thì thì của động từ 1 luôn ở thể từ điển."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"１）日本へ 来る 前に、日本語を 勉 強 しました。",romaji:"１）日本e 来ru 前ni、日本語o 勉 強 shimashita。",vi:"(Tôi đã học tiếng Nhật trước khi đến Nhật)"},{ja:"２）寝る まえに、本を 読みます。",romaji:"２）寝ru maeni、本o 読mimasu。",vi:"(Trước khi đi ngủ, tôi đọc sách)"},{ja:"- Thêm trợ từ の ở giữa danh từ và まえに",romaji:"- Thêm trợ từ no ở giữa danh từ và maeni",vi:"Ví dụ minh họa"},{ja:"- Danh từ đứng trước まえに là những danh từ biểu thị hành động",romaji:"- Danh từ đứng trước maeni là những danh từ biểu thị hành động",vi:"Ví dụ minh họa"},{ja:"１）食事の まえに、手を洗います。",romaji:"１）食事no maeni、手o洗imasu。",vi:"(Trước bữa cơm/Trước khi ăn cơm, (tôi) rửa tay."},{ja:"２）講義の まえに、事務所へ 行ってください。",romaji:"２）講義no maeni、事務所e 行っtekudasai。",vi:"(Hãy đến văn phòng trước giờ học)"},{ja:"- Đứng sau danh từ chỉ số thì không cần の",romaji:"- Đứng sau danh từ chỉ số thì không cần no",vi:"Ví dụ minh họa"},{ja:"１）３年前に、結婚しました。(Tôi đã kết hôn cách đây 3 năm)",romaji:"１）３年前ni、結婚shimashita。(Tôi đã kết hôn cách đây 3 năm)",vi:"Ví dụ minh họa"},{ja:"２）田中さんは １時間前に、出かけました。(Tanaka đã ra ngoài cách đây 1 tiếng)",romaji:"２）田中sanwa １時間前ni、出kakemashita。(Tanaka đã ra ngoài cách đây 1 tiếng)",vi:"Ví dụ minh họa"}]},{id:4115,lesson:18,level:"N5",title:"なかなか",meaning:"mãi mà không…",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"１）日本で なかなか 馬を 見ることが できません。",romaji:"１）日本de nakanaka 馬o 見rukotoga dekimasen。",vi:"(Ở Nhật, mãi mà tôi không thể nhìn thấy con ngựa nào)"},{ja:"２）バスが なかなか 来ません。",romaji:"２）バスga nakanaka 来masen。",vi:"(Xe buýt mãi mà không thấy tới)"}]},{id:4116,lesson:18,level:"N5",title:"ぜひ",meaning:"nhất định",usage:["thường đi với các dạng câu ほしいです、V たいです、V てください","với ý nghĩa nhấn mạnh sự biểu thị"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"１）ぜひ 北海道へ",romaji:"１）zehi 北海道e",vi:"行きたいです。(Tôi rất muốn đi Hokkaido (nhất định sẽ đi))"},{ja:"２）ぜひ 遊びに 来てください。 (Bạn nhất định phải đến nhà tôi chơi đấy nhé!)",romaji:"２）zehi 遊bini 来tekudasai。 (Bạn nhất định phải đến nhà tôi chơi đấy nhé!)",vi:"Ví dụ minh họa"}]},{id:4117,lesson:19,level:"N5",title:"Bài 19 - Điểm ngữ pháp chính",meaning:"Bài 19 - Điểm ngữ pháp chính",usage:["ĐỘNG TỪ QUÁ KHỨ DẠNG NGẮN (V た) & CÁC MẪU CÂU","１．Cách tạo động từ thể た:  giống y như thể て","Chỗ nào chia là て và で thì thay bằng た và だ.","Nhóm I:","かいて → かいた","のんで → のんだ","Nhóm II:","たべて → たべた","みて → みた","Nhóm III:","きて → きた","して → した","CÁC MẪU CÂU VỚI ĐỘNG TỪ THỂ た","Cách thể hiện kinh"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 19 - Điểm ngữ pháp chính",romaji:"Bài 19 - Điểm ngữ pháp chính",vi:"Bài 19 - Điểm ngữ pháp chính"}]},{id:4118,lesson:19,level:"N5",title:"V たことが あります nghiệm trong quá khứ",meaning:"đã từng (làm)...",usage:["Dùng theo cấu trúc ngữ pháp chuẩn trong giao tiếp."],notes:["thể câu văn này khác cơ bản với thể câu văn muốn diễn tả một hành động","chỉ đơn thuần xảy ra ở quá khứ."],examples:[{ja:"１）馬に",romaji:"１）馬ni",vi:"乗ったことが あります。(Tôi đã từng cưỡi ngựa)"},{ja:"２） 桜 を",romaji:"２） 桜 o",vi:"見たことが あります。(Tôi đã từng nhìn thấy hoa anh đào)"},{ja:"１）去年 北海道で 馬に",romaji:"１）去年 北海道de 馬ni",vi:"乗りました。(Năm ngoái tôi đã cưỡi ngựa ở Hokkaido)"},{ja:"２） 先 週",romaji:"２） 先 週",vi:"桜 を 見ました。(Tuần trước, tôi đã nhìn thấy hoa anh đào)"},{ja:"日本へ 行 ったことが ありますか。(Bạn đã bao giờ đi Nhật Bản chưa)",romaji:"日本e 行 っtakotoga arimasuka。(Bạn đã bao giờ đi Nhật Bản chưa)",vi:"Ví dụ minh họa"},{ja:"… はい、あります／…はい、３回 あります。(Có, đã từng/Có, đã 3 lần)",romaji:"… wai、arimasu／…wai、３回 arimasu。(Có, đã từng/Có, đã 3 lần)",vi:"Ví dụ minh họa"},{ja:"… いいえ、ありません／…いいえ、一度も ありません。(Chưa lần nào)",romaji:"… iie、arimasen／…iie、一度mo arimasen。(Chưa lần nào)",vi:"Ví dụ minh họa"}]},{id:4119,lesson:19,level:"N5",title:"V たり、V たり します Cách liệt kê hành động (nhưng không",meaning:"trở nên (được)",usage:["quan tâm đến thứ tự diễn ra)","hành động mà chủ thể thực hiện mà không cần biết cái nào xảy ra trước,","cái nào xảy ra sau","thì của mẫu câu được biểu thị ở cuối câu.","さむ さむ","１）寒いです → 寒く なります","げんき げんき","２）元気「な」 → 元気に なります","さい さい","３）25歳 → 25歳に なります"],notes:["không nhầm với câu văn sử dụng て để nối câu đã học ở bài 16.","にちようび えいが み","１）日曜日は テニスを したり、映画を 見たり します。","(Chủ Nhật, lúc thì tôi chơi tenis, lúc thì xem phim.)","にちようび えいが","２）日曜日は テニスを して、映画を みます。","(Chủ Nhật, tôi chơi tenis, xong rồi xem phim.)","Ở câu 2 ý nghĩa là hành động xem phim diễn ra sau khi chơi tennis.","Ở câu 1 không có mối quan hệ về mặt thời gian giữa hai hành động. Trong rất","nhiều các hoạt động diễn ra vào ngày chủ nhật sẽ bao gồm hai hành động chơi","tennis và xem phim. Và sẽ không tự nhiên khi dùng để liệt kê những hành động","mang tính chất hàng ngày của con người như ngủ dậy, ăn cơm hay đi ngủ...","４．A い（～い）→ ～く Cách nối tính từ với động từ","A な「な」→ に なります  biến tính từ thành phó từ","Nに"],examples:[{ja:"１）日曜日は テニスを したり、映画を 見たり します。",romaji:"１）日曜日wa テニスo shitari、映画o 見tari shimasu。",vi:"(Chủ Nhật, lúc thì tôi chơi tenis, lúc thì xem phim.)"},{ja:"２）昨日 買い物したり、音楽を 聞いたり しました。",romaji:"２）昨日 買i物shitari、音楽o 聞itari shimashita。",vi:"(Hôm qua, lúc thì tôi đi mua sắm, lúc thì nghe nhạc)"}]},{id:4120,lesson:20,level:"N5",title:"Thể văn thông thường và thể văn lịch sự",meaning:"Thể văn thông thường và thể văn lịch sự",usage:["Thể lịch sự: là cách nói mà kết thúc câu luôn là –desu (với tính từ, danh từ) và –masu","(với động từ) và các dạng phái sinh của nó (-deshita, -dewa arimasen, -masen, -mashita) .","Thể thông thường: là cách nói không có –desu hay –masu. Dùng luôn dạng cơ bản,","dạng gốc và các dạng phái sinh dạng ngắn của các loại từ đó.","Thể lịch sự Thể thông thường"," ","① Người lớn tuổi a. Người kém tuổi","② Người gặp lần đầu tiên b. Người ngang tuổi","③ Cấp trên c. Bạn thân","④ Mình là nhân viên mới d. Người trong gia đình","⑤ Trong các sự kiện nghiêm túc (họp","hành, phát biểu…)"],notes:["(1) Trong trường hợp từ ① đến ⑤ mà sử dụng thể thông thường thì bị coi là thất lễ.","(2) Người Nhật đối với người nước ngoài hay nhân viên lâu năm khi chỉ đạo, hướng dẫn nhân","viên mới để thể hiện sự thân mật tùy thuộc vào ý đồ vẫn có thể sử dụng được thể thông","thường.","(3) Từ a~d, cũng tùy thuộc vào trường hợp vẫn có thể sử dụng thể lịch sự"],examples:[{ja:"Thể văn thông thường và thể văn lịch sự",romaji:"Thể văn thông thường và thể văn lịch sự",vi:"Thể văn thông thường và thể văn lịch sự"}]},{id:4121,lesson:20,level:"N5",title:"Trình bày về thể văn lịch sự và thông thường",meaning:"Bài",usage:["a. Thể văn lịch sự và thông thường của động từ, tính từ, danh từ","Thể lịch sự Thể thông thường","かきます かく(thể từ điển)","かきません かかない (thể ない)","Động từ かきました かいた (thể た)","かきませんでした かかなかった (thể ない quá khứ)","あついです あつい (bỏ です)","Tính từ -i あつくないです あつくない","Tính từ -na あつかったです あつかった","Danh từ あつくなかったです あつくなかった","ひまです ひまだ","ひまではありません ひまではない","ひまでした ひまだった","ひまではありませんでした ひまではなかった","b. Thể văn lịch sự và thông thường của các nhóm từ ngữ theo sau"],notes:["Khi đổi những câu được nối với nhau bằng から hay が、けど (thường sử dụng trong hội","thoại) thành thể văn thông thường thì tất cả các từ lịch sự trong câu phải được đổi sang thể","thông thường.","いた びょういん い","１）おなかが 痛いですから、 病 院 へ 行きます。","→ おなかが 痛いから、 病 院 へ いく。","にほん もの たか","２）日本の食べ物は おいしいですが、高いです。","にほん もの たか","→ 日本の食べ物は おいしいが、高い。"],examples:[{ja:"Trình bày về thể văn lịch sự và thông thường",romaji:"Trình bày về thể văn lịch sự và thông thường",vi:"Bài"}]},{id:4122,lesson:20,level:"N5",title:"Câu nghi vấn ở thể văn thông thường",meaning:"Câu nghi vấn ở thể văn thông thường",usage:["bỏ trợ từ chỉ sự nghi vấn là か ở cuối câu, thay vào đó đọc cao giọng chữ ở cuối câu để","biểu thị sự nghi vấn."],notes:["cũng có những câu nghi vấn ở thể văn thông thường mà không bỏ chữ か ở","sau như: 飲むか、見たか…, nhưng chỉ được sử dụng giới hạn trong phạm vi nam","giới khi người trên hỏi người dưới hoặc những người quá thân nhau (như cha hỏi","con trai)","Đối với câu nghi vấn danh từ hay tính từ thì chữ だ thể thông thường của です được","giản lược."],examples:[{ja:"１）コーヒーを 飲む？（ ）",romaji:"１）コーヒーo 飲mu？（ ）",vi:"Ví dụ minh họa"},{ja:"…うん、飲む（",romaji:"…un、飲mu（",vi:"）"},{ja:"今晩 暇？",romaji:"今晩 暇？",vi:"Ví dụ minh họa"},{ja:"…うん、暇（だよ）",romaji:"…un、暇（dayo）",vi:"Ví dụ minh họa"},{ja:"…ううん、暇ではない。",romaji:"…uun、暇dewanai。",vi:"Ví dụ minh họa"},{ja:"…ううん、暇じゃない。",romaji:"…uun、暇jiゃnai。",vi:"Ví dụ minh họa"},{ja:" Khi đàm thoại thường dùng じゃない",romaji:" Khi đàm thoại thường dùng jiゃnai",vi:"- Trợ từ trong câu nghi vấn ở thể văn thông văn cũng thường được lược bỏ"},{ja:"１）ご飯「を」食べる？",romaji:"１）go飯o食beru？",vi:"Ví dụ minh họa"},{ja:"２）明日 京都「へ」行かない？",romaji:"２）明日 京都e行kanai？",vi:"Ví dụ minh họa"},{ja:"３）このりんご「は」おいしいですね。",romaji:"３）konoringowaoishiidesune。",vi:"Ví dụ minh họa"},{ja:"４）そこに はさみ「が」ある？",romaji:"４）sokoni wasamigaaru？",vi:"Ví dụ minh họa"},{ja:"- Trong thể thông thường, chữ い trong mẫu câu V ている cũng thường được lược bỏ",romaji:"- Trong thể thông thường, chữ i trong mẫu câu V teiru cũng thường được lược bỏ",vi:"Ví dụ minh họa"},{ja:"１）辞書、持って「い」る？",romaji:"１）辞書、持っteiru？",vi:"Ví dụ minh họa"},{ja:"…うん、持って「い」る。",romaji:"…un、持っteiru。",vi:"Ví dụ minh họa"},{ja:"…ううん、持って「い」ない。",romaji:"…uun、持っteinai。",vi:"Ví dụ minh họa"}]},{id:4123,lesson:20,level:"N5",title:"Thể thông thường của はい、いいえ",meaning:"Thể thông thường của はい、いいえ",usage:["はい → うん","いいえ → ううん (phát âm u u n )","JAPANESE ELEMENTARY III","GRAMMAR","EXPLANATION","(Lesson 21 – Lesson 30)","FU - 2009","FPT University Tiếng Nhật cơ sở 3"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Thể thông thường của はい、いいえ",romaji:"Thể thông thường của wai、iie",vi:"Thể thông thường của はい、いいえ"}]},{id:4124,lesson:21,level:"N5",title:"Bài 21 - Điểm ngữ pháp chính",meaning:"Bài 21 - Điểm ngữ pháp chính",usage:["CÁC MẪU CÂU VỚI THÊ THÔNG THƯỜNG","Thể thông thường + と おもいます。 (cách thể hiện suy nghĩ, quan điểm"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 21 - Điểm ngữ pháp chính",romaji:"Bài 21 - Điểm ngữ pháp chính",vi:"Bài 21 - Điểm ngữ pháp chính"}]},{id:4125,lesson:21,level:"N5",title:"của cá nhân)",meaning:"(tôi) nghĩ rằng ~ / (tôi) cho rằng ~",usage:["Động từ V る･V ない･V た","Tính từ đuôi i ～い","dạng","Tính từ đuôi na","ngắn ～だ と おもいます","Danh từ","～だ"],notes:["(1) Khi nói câu phủ định, có 2 cách thể hiện","Xem ví dụ sau:","日本語のテストは どうですか。 Bài kiểm tra tiếng Nhật thế nào?","① … むずかしくないと 思います。Tôi nghĩ là không khó.","② … むずかしいと 思いません。Tôi không nghĩ là khó.","Cả 2 đều thể hiện sự phỏng đoán, ý kiến ở thể phủ định, nhưng về ý nghĩa có chút khác biệt. Cách","nói thứ ② có ý nghĩa phủ định mạnh hơn.","Tuy nhiên, trong sơ cấp và trong bài này, chúng ta chỉ dùng cách nói ①","FPT University Tiếng Nhật cơ sở 3","(2) Cách nói ngắn khi đồng ý hay không đồng ý với quan điểm của ai đó:","A: ファクスは 便利ですね。 Máy fax thuận tiện thật đấy nhỉ!","B: 私も そう思います。 Tôi cũng nghĩ như vậy","わたし おも","C: 私は そう［は］思いません。Tôi thì không nghĩ là như vậy","(3) Câu hỏi: khi muốn hỏi quan điểm của ai đó về 1 vấn đề nào đó, ta dùng mẫu câu","～に ついて どう思いますか (không cần trợ từ と sau どう nữa)"],examples:[{ja:"① 明日 雨が",romaji:"① 明日 雨ga",vi:"降ると"},{ja:"② テレサちゃんは",romaji:"② テレサchiゃnwa",vi:"もう"},{ja:"③ かれは 日本語が",romaji:"③ karewa 日本語ga",vi:"分からないと"},{ja:"④ あのカメラは",romaji:"④ anoカメラwa",vi:"よくないと"},{ja:"⑤ 彼女は",romaji:"⑤ 彼女wa",vi:"日本人だと"},{ja:"⑥ 日よう日は ひまだと",romaji:"⑥ 日you日wa himadato",vi:"思います。Tôi nghĩ Chủ Nhật thì rỗi."},{ja:"新 しい空港に",romaji:"新 shii空港ni",vi:"ついて"},{ja:"…きれいですが、ちょっと交通が",romaji:"…kireidesuga、chiょっto交通ga",vi:"不便だと"}]},{id:4126,lesson:21,level:"N5",title:"“Sentence”",meaning:"(ai đó) nói rằng / đã nói rằng ～",usage:["(cách trích dẫn trực tiếp hoặc gián","と 言います","い tiếp 1 câu nói, 1 ý kiến mà ai đó đã","Dạng thông thường đưa ra)","言いました。","Động từ V る･V ない･V た","Tính từ đuôi i ～い","dạng","Tính từ đuôi na","ngắn ～だ と いいます","Danh từ","～だ","Có 2 kiểu trích dẫn:","(1) Trích dẫn trực tiếp: nhắc lại chính xác nội dung câu nói  để nội dung đó trong ngoặc kép「 」","ね まえ やす い","① 寝る前に「お休みなさい」と 言います。Trước khi đi ngủ thì nói “Chúc ngủ ngon”.","らいしゅう とうきょう しゅっちょう い","② ミラーさんは「 来 週 東 京へ 出 張 します」と 言いました。","Ông Miler đã nói rằng “Tuần sau tôi sẽ đi công tác Tokyo”.","(2) Trích dẫn gián tiếp: sử dụng thể thông thường trước trợ từ と.","Thì của câu trích dẫn không bị ảnh hưởng bởi thì của câu chính.","らいしゅう とうきょう しゅっちょう い","ミラーさんは 来週 東 京 へ 出 張 すると 言いました。","Ông Miler đã nói rằng tuần sau ống ấy sẽ đi công tác Tokyo.","FPT University Tiếng Nhật cơ sở 3","V (cách xác nhận 1 thông tin nào đó với"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"“Sentence”",romaji:"“Sentence”",vi:"(ai đó) nói rằng / đã nói rằng ～"}]},{id:4127,lesson:21,level:"N5",title:"thể thông thường",meaning:"～có đúng không? / ～có đúng không nhỉ?  giống câu hỏi đuôi trong tiếng Anh",usage:["い－Adj mong muốn người nghe tán đồng với","でしょう？ ý kiến của mình)","な－Adj thể thông thường","N ～だ","và mong muốn người nghe sẽ tán thành ý kiến của mình. でしょう được đọc lên","giọng giống như 1 câu hỏi để xác nhận sự đồng tình của người nghe.","＊ Cách chia: trước でしょう là thể thông thường. Tuy nhiên đối với tính từ đuôi -な và danh từ,","bỏ だ và ghép thẳng với でしょう."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"…ええ、行きます。Ừ, đi chứ.",romaji:"…ee、行kimasu。Ừ, đi chứ.",vi:"Ví dụ minh họa"},{ja:"…いいえ、そんなに寒くなかったです。Không, không lạnh đến thế đâu.",romaji:"…iie、sonnani寒kunakaっtadesu。Không, không lạnh đến thế đâu.",vi:"Ví dụ minh họa"},{ja:"…はい、にぎやかです。Vâng, rất nhộn nhịp.",romaji:"…wai、nigiyakadesu。Vâng, rất nhộn nhịp.",vi:"Ví dụ minh họa"}]},{id:4128,lesson:21,level:"N5",title:"N1 (địa điểm)で N2 があります。",meaning:"ở N1 được tổ chức, diễn ra N2",usage:["thì lúc đó あります có nghĩa là được tổ chức, diễn ra."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"N1 (địa điểm)で N2 があります。",romaji:"N1 (địa điểm)de N2 gaarimasu。",vi:"ở N1 được tổ chức, diễn ra N2"}]},{id:4129,lesson:21,level:"N5",title:"東 京 で 日本とブラジルの サッカー試合が あります。",meaning:"東 京 で 日本とブラジルの サッカー試合が あります。",usage:["Ở Tokyo sẽ (có) diễn ra trận bóng đá giữa Nhật Bản và Braxin"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"東 京 で 日本とブラジルの サッカー試合が あります。",romaji:"東 京 de 日本toブラジルno サッカー試合ga arimasu。",vi:"東 京 で 日本とブラジルの サッカー試合が あります。"}]},{id:4130,lesson:21,level:"N5",title:"神戸で 大きい 地震が ありました。",meaning:"神戸で 大きい 地震が ありました。",usage:["Ở Kobe đã (có) xảy ra trận động đất lớn","FPT University Tiếng Nhật cơ sở 3"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"神戸で 大きい 地震が ありました。",romaji:"神戸de 大kii 地震ga arimashita。",vi:"神戸で 大きい 地震が ありました。"}]},{id:4131,lesson:22,level:"N5",title:"Bài 22 - Điểm ngữ pháp chính",meaning:"Bài 22 - Điểm ngữ pháp chính",usage:["ĐỊNH NGỮ"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 22 - Điểm ngữ pháp chính",romaji:"Bài 22 - Điểm ngữ pháp chính",vi:"Bài 22 - Điểm ngữ pháp chính"}]},{id:4132,lesson:22,level:"N5",title:"Các cách bổ nghĩa cho danh từ:",meaning:"Các cách bổ nghĩa cho danh từ:",usage:["Đã học: bổ nghĩa bằng đơn vị từ","ミラーさんの 家 Ngôi nhà của anh Miler (bài 2)","新 しい 家 Ngôi nhà mới (bài 8)","きれいな 家 Ngôi nhà đẹp (bài 8)","Bài này học: bổ nghĩa bằng đơn vị câu với động từ ( định ngữ)"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Các cách bổ nghĩa cho danh từ:",romaji:"Các cách bổ nghĩa cho danh từ:",vi:"Các cách bổ nghĩa cho danh từ:"}]},{id:4133,lesson:22,level:"N5",title:"Cách cấu thành định ngữ: (bổ nghĩa danh từ bằng câu động từ)",meaning:"Cách cấu thành định ngữ: (bổ nghĩa danh từ bằng câu động từ)",usage:["dạng","Động từ ngắn","V る･V ない･V た DANH TỪ","行く人 Người sẽ đi Kyoto","行かない人 Người không đi Kyoto","京都へ","行った人 Người đã đi Kyoto","行かなかった人 Người đã không đi Kyoto","Các danh từ đóng vai trò là các yếu tố khác nhau trong câu có thể được chọn ra và bổ nghĩa bằng chính","động từ của câu đó  định ngữ:"],notes:["Khi các danh từ được bổ nghĩa thì các trợ từ を, で, に ở câu gốc sẽ không cần nữa","FPT University Tiếng Nhật cơ sở 3","Định ngữ (danh từ được bổ nghĩa bằng câu động từ ) có thể ở nhiều vị trí trong câu, đóng vai trò nhiều","thành phần của câu (như 1 danh từ bình thường)"],examples:[{ja:"② ワンさんは",romaji:"② ワンsanwa",vi:"病 院で"}]},{id:4134,lesson:22,level:"N5",title:"Nが",meaning:"Nが",usage:["hành động) trong câu bổ nghĩa đó được xác định bởi trợ từ が"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"ミラーさんは",romaji:"ミラーsanwa",vi:"ケーキを"},{ja:"→ これは",romaji:"→ korewa",vi:"ミラーさんが"},{ja:"カリナさんは",romaji:"カリナsanwa",vi:"絵を"},{ja:"→ わたしは",romaji:"→ watashiwa",vi:"カリナさんが"}]},{id:4135,lesson:23,level:"N5",title:"～ とき、～ (cách thể hiện ý nói: khi (làm gì) thì (làm gì))",meaning:"khi ～, lúc ～",usage:["cấu thành mẫu câu này áp dụng toàn bộ quy tắc bổ nghĩa danh từ hay tạo 1 định ngữ (đối với","động từ)","Động từ dạng ngắn V る･V ない･V た","Tính từ đuôi i ～い","Tính từ đuôi na ～な","Danh từ","～の","cũng khác nhau. Cụ thể:","V る: biểu thị một hành động chưa hoàn thành.","V た: biểu thị một việc, hành động hay tình trạng đã hoàn tất"],notes:["thì của câu tính từ và câu danh từ bổ nghĩa cho とき không bị ảnh hưởng bởi thì của mệnh đề","chính trong câu. (ví dụ 6 và 7)","FPT University Tiếng Nhật cơ sở 3","Vる (phân biệt giữa V る＋とき、và V た＋とき)","2．","Vた とき、～"],examples:[{ja:"① 図書館で",romaji:"① 図書館de",vi:"本を借りるとき、カードが"},{ja:"② 使い方が",romaji:"② 使i方ga",vi:"分からないとき、 私 に"},{ja:"④ 暇なとき、うちへ 遊びに行きませんか。",romaji:"④ 暇natoki、uchie 遊bini行kimasenka。",vi:"Bạn sẽ đến nhà tôi chơi khi rảnh rỗi chứ?"},{ja:"⑤ 妻が",romaji:"⑤ 妻ga",vi:"病気のとき、会社を"},{ja:"⑥ 子供のとき、よく 川で",romaji:"⑥ 子供notoki、yoku 川de",vi:"泳ぎました。"},{ja:"⑦ 若いとき、あまり",romaji:"⑦ 若itoki、amari",vi:"勉 強 しませんでした。"}]},{id:4136,lesson:23,level:"N5",title:"V る (cách nói giả định, giả sử",meaning:"Nếu… thì…; cứ … thì sẽ…",usage:["V ない と、～ loại 1: về 1 sự việc chắn chắn sẽ xảy ra )","động nào đó mà 1 hành động, 1 sự việc khác chắn chắn sẽ xảy ra. Trợ từ と (mang","nghĩa là “nếu”) được đặt ở giữa để nối 2 câu và đóng vai trò xác định mệnh đề giả sử."],notes:["mệnh đề đứng sau ~と không sử dụng để biểu hiện một ý hướng, một hy vọng, một sự","rủ rê hay một sự nhờ vả.","映画を 見に行きます。 thì sẽ đi xem phim. (ý hướng)","じかん えいが み い","× 時間が あると、 映画を 見に行きたいです。 thì muốn đi xem phim. (hy vọng)","Nếu có thời gian 映画を 見に行きませんか。 thì có đi xem phim không? (rủ rê)","ちょっと手伝ってください。 thì hãy giúp một chút. (nhờ vả)","Kiểu giả sử này chúng ta sẽ học ở bài 25 với mẫu câu 「～たら」"],examples:[{ja:"① このボタンを",romaji:"① konoボタンo",vi:"押すと、お釣りが"},{ja:"② これを",romaji:"② koreo",vi:"回すと、音が"},{ja:"③ 右へ",romaji:"③ 右e",vi:"曲がると、郵 便 局 が"},{ja:"に ほ ん ご",romaji:"ni ho n go",vi:"わ"},{ja:"④ 日本語が",romaji:"④ 日本語ga",vi:"分からないと、困りますよ。"},{ja:"⑤ もっと",romaji:"⑤ moっto",vi:"がんばらないと、合格できません。"}]},{id:4137,lesson:23,level:"N5",title:"Nが Adj／V",meaning:"Nが Adj／V",usage:["sau chủ ngữ sẽ là が"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"① 音が",romaji:"① 音ga",vi:"小さいです。"},{ja:"② 天気が",romaji:"② 天気ga",vi:"明るくなりました。"},{ja:"③ この",romaji:"③ kono",vi:"ボタンを"}]},{id:4138,lesson:23,level:"N5",title:"あるきます: đi bộ",meaning:"あるきます: đi bộ",usage:["N (địa điểm) を V (động từ di chuyển) わたります: băng qua","さんぽします: đi dạo"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"① 橋を",romaji:"① 橋o",vi:"渡ります。"},{ja:"② 公園を",romaji:"② 公園o",vi:"散歩します。"},{ja:"③ 交差点を",romaji:"③ 交差点o",vi:"右へ"}]},{id:4139,lesson:24,level:"N5",title:"Bài 24 - Điểm ngữ pháp chính",meaning:"Bài 24 - Điểm ngữ pháp chính",usage:["(cách thể hiện hành động ai đó cho, tặng","N をくれます"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Bài 24 - Điểm ngữ pháp chính",romaji:"Bài 24 - Điểm ngữ pháp chính",vi:"Bài 24 - Điểm ngữ pháp chính"}]},{id:4140,lesson:24,level:"N5",title:"mình hoặc người thân trong gia đình mình cái gì )",meaning:"cho (người nói)",usage:["chỗ あげます chỉ dùng khi thể hiện việc người nói tặng cho ai, người nào đó tặng cho người khác","chứ không dùng để thể hiện việc ai đó tặng, cho người nói hoặc người thân trong gia đình người nói."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Trong trường hợp này, chúng ta dùng động từ くれます thay thế.",romaji:"Trong trường hợp này, chúng ta dùng động từ kuremasu thay thế.",vi:"Ví dụ minh họa"},{ja:"① 佐藤さんは",romaji:"① 佐藤sanwa",vi:"私に"},{ja:"② 佐藤さんは",romaji:"② 佐藤sanwa",vi:"妹 に"},{ja:"Cả あげます、もらいます、くれます đều dùng để thể hiện hành động cho, tặng, biếu, nhận 1 vật",romaji:"Cả agemasu、moraimasu、kuremasu đều dùng để thể hiện hành động cho, tặng, biếu, nhận 1 vật",vi:"nào đó. Chúng cũng được sử dụng để thể hiện sự cho và nhận các hành động: ai làm gì đó cho ai đồng"}]},{id:4141,lesson:24,level:"N5",title:"V てあげます (cách nói làm gì đó cho ai)",meaning:"nhận (việc gì) từ ai; được ai đó làm gì cho",usage:["chủ ngữ là người nhận"],notes:["- Khi người nói là người thực hiện hành động và người nghe là người nhận hành động, thì cách thể","hiện này có thể gây cảm giác người nói đang ra vẻ bề trên. Vì vậy, cần chú ý tránh sử dụng cách nói này","đối người lớn hay cấp trên, người không mấy thân thiết, chỉ nên sử dụng với người thân thiết.","Khi muốn nói ý tương từ đối với người không thân thiết thì sử dụng mẫu câu V ましょうか."],examples:[{ja:"V てもらいます",romaji:"V temoraimasu",vi:"(cách nói nhận được việc gì đó do ai làm cho)"}]},{id:4142,lesson:24,level:"N5",title:"V てくれます (cách nói ai đó làm gì cho mình)",meaning:"ai làm cho cái gì",usage:["hành vi giúp đỡ.","khác với ～てもらいます chủ ngữ là người nhận, còn trong câu ～てくれます","chủ ngữ là người thực hiện hành động.","người nhận thường là người nói nên 私に (chỉ người nhận) thường được lược bỏ."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"V てくれます (cách nói ai đó làm gì cho mình)",romaji:"V tekuremasu (cách nói ai đó làm gì cho mình)",vi:"ai làm cho cái gì"}]},{id:4143,lesson:25,level:"N5",title:"Biểu hiện điều kiện",meaning:"khi, sau khi",usage:["V","A (cách nói giả định, giả sử","Na Thể quá khứ thông thường + ら、～ loại 2: dùng cho hầu hết các tình huống )","N","Động từ Vた","Tính từ đuôi i ～かった","Tính từ đuôi na ～だった","Danh từ","～だった","đứng trước nó thành mệnh đề biểu hiện điều kiện.","có thể dùng khi người nói muốn bày tỏ lập trường, ý kiến, yêu cầu, lời mời… của","mình trong điều kiện đó.","hành động sẽ được thực hiện, hoặc 1 tình huống sẽ xẩy ra khi 1 sự việc nào đó mà được cho là chắc","chắn sẽ xảy ra trong tương lai được hoàn thành hoặc đạt được. Thì của mệnh đề chính luôn ở thời","hiện tại","FPT University Tiếng Nhật cơ sở 3"],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"V たら、～",romaji:"V tara、～",vi:"(ý nghĩa thứ 2 của mẫu câu ～たら: khi, sau khi )"},{ja:"…昼ごはんを 食べたら、すぐ 行きます。",romaji:"…昼gowano 食betara、sugu 行kimasu。",vi:"Sau khi ăn cơm trưa xong là đi ngay."}]},{id:4144,lesson:25,level:"N5",title:"Biểu hiện về giả thuyết tương phản",meaning:"dù…, mặc dù…, cho dù…",usage:["Vて (cách nói mệnh đề ngược nghĩa )","い－Adj（～い）→ ～くて","な－Adj「な」→で も、～","Nで","ngược với mẫu câu ～たら, mẫu câu ～ても dùng trong tình huống hy vọng một","việc gì đó đương nhiên sẽ xảy ra trong điều kiện cho trước nhưng lại không xảy ra,","hoặc kết quả xảy ra trái ngược với những gì đã kỳ vọng.","もし được sử dụng trong mẫu câu ~たら、bao hàm ý nhấn mạnh về giả thuyết của người nói.","いくら được sử dụng trong mẫu câu ~ても（～でも）, nhấn mạnh về mức độ điều kiện."],notes:"Chú ý ngữ cảnh sử dụng và sắc thái của câu.",examples:[{ja:"Biểu hiện về giả thuyết tương phản",romaji:"Biểu hiện về giả thuyết tương phản",vi:"dù…, mặc dù…, cho dù…"}]}];export{n as GRAMMAR_N5};
